screenPanels.initJs:
function(container, apiUrl, tables) {
  // 言語設定
  const languages = {
    ja: {
      title: 'ハイブリッド申請承認システム',
      subtitle: 'Hybrid Application Approval System',
      userId: 'ユーザーID',
      password: 'パスワード',
      rememberMe: 'ログイン状態を保持する',
      login: 'ログイン',
      forgotPassword: 'パスワードを忘れた方はこちら',
      help: 'ヘルプ・お問い合わせ',
      languageSelect: '言語選択',
      close: '閉じる',
      userIdPlaceholder: 'ユーザーIDを入力してください',
      passwordPlaceholder: 'パスワードを入力してください',
      errorRequired: 'ユーザーIDとパスワードを入力してください',
      errorUserIdRequired: 'ユーザーIDを入力してください',
      errorPasswordRequired: 'パスワードを入力してください',
      errorInvalidCredentials: 'ユーザーIDまたはパスワードが正しくありません',
      errorAccountLocked: 'アカウントがロックされています。管理者にお問い合わせください'
    },
    en: {
      title: 'Hybrid Application Approval System',
      subtitle: 'Hybrid Application Approval System',
      userId: 'User ID',
      password: 'Password',
      rememberMe: 'Remember me',
      login: 'Login',
      forgotPassword: 'Forgot your password?',
      help: 'Help & Support',
      languageSelect: 'Language Selection',
      close: 'Close',
      userIdPlaceholder: 'Enter your user ID',
      passwordPlaceholder: 'Enter your password',
      errorRequired: 'Please enter user ID and password',
      errorUserIdRequired: 'Please enter user ID',
      errorPasswordRequired: 'Please enter password',
      errorInvalidCredentials: 'Invalid user ID or password',
      errorAccountLocked: 'Account is locked. Please contact administrator'
    },
    zh: {
      title: '混合申请审批系统',
      subtitle: 'Hybrid Application Approval System',
      userId: '用户ID',
      password: '密码',
      rememberMe: '保持登录状态',
      login: '登录',
      forgotPassword: '忘记密码？',
      help: '帮助与支持',
      languageSelect: '语言选择',
      close: '关闭',
      userIdPlaceholder: '请输入用户ID',
      passwordPlaceholder: '请输入密码',
      errorRequired: '请输入用户ID和密码',
      errorUserIdRequired: '请输入用户ID',
      errorPasswordRequired: '请输入密码',
      errorInvalidCredentials: '用户ID或密码错误',
      errorAccountLocked: '账户已锁定，请联系管理员'
    }
  };

  let currentLang = 'ja';
  let loginAttempts = 0;
  const maxAttempts = 5;

  // DOM要素の取得
  const loginForm = container.querySelector('#login-form');
  const userIdInput = container.querySelector('#user-id');
  const passwordInput = container.querySelector('#password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const errorMessage = container.querySelector('#error-message');
  const languageToggle = container.querySelector('#language-toggle');
  const languageMenu = container.querySelector('#language-menu');
  const currentLanguageSpan = container.querySelector('#current-language');
  const forgotPasswordLink = container.querySelector('#forgot-password-link');
  const helpLink = container.querySelector('#help-link');

  // 言語切り替え関数
  function updateLanguage(lang) {
    currentLang = lang;
    const texts = languages[lang];

    container.querySelector('h1').textContent = texts.title;
    container.querySelector('p').textContent = texts.subtitle;
    container.querySelector('label[for="user-id"]').textContent = texts.userId;
    container.querySelector('label[for="password"]').textContent = texts.password;
    container.querySelector('label[for="remember-me"]').lastChild.textContent = ' ' + texts.rememberMe;
    container.querySelector('#login-button').textContent = texts.login;
    forgotPasswordLink.textContent = texts.forgotPassword;
    helpLink.textContent = texts.help;
    container.querySelector('h3').textContent = texts.languageSelect;
    container.querySelector('#close-language-menu').textContent = texts.close;

    userIdInput.placeholder = texts.userIdPlaceholder;
    passwordInput.placeholder = texts.passwordPlaceholder;

    const langNames = { ja: '日本語', en: 'English', zh: '中文' };
    currentLanguageSpan.textContent = langNames[lang];
  }

  // エラーメッセージ表示
  function showError(messageKey) {
    const message = languages[currentLang][messageKey];
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
  }

  function hideError() {
    errorMessage.style.display = 'none';
  }

  // パスワード表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '🙈' : '👁';
  });

  // 言語切り替えメニュー
  languageToggle.addEventListener('click', () => {
    languageMenu.style.display = 'block';
  });

  container.querySelector('#close-language-menu').addEventListener('click', () => {
    languageMenu.style.display = 'none';
  });

  languageMenu.addEventListener('click', (e) => {
    if (e.target === languageMenu) {
      languageMenu.style.display = 'none';
    }
  });

  // 言語選択
  container.addEventListener('click', (e) => {
    const langOption = e.target.closest('.language-option');
    if (langOption) {
      const lang = langOption.dataset.lang;
      updateLanguage(lang);
      languageMenu.style.display = 'none';
    }
  });

  // フォーカス時のスタイル
  [userIdInput, passwordInput].forEach(input => {
    input.addEventListener('focus', () => {
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });

    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });

  // ログインボタンのホバー効果
  const loginButton = container.querySelector('#login-button');
  loginButton.addEventListener('mouseenter', () => {
    loginButton.style.background = 'var(--primary-hover)';
  });

  loginButton.addEventListener('mouseleave', () => {
    loginButton.style.background = 'var(--primary)';
  });

  // バリデーション
  function validateForm() {
    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();

    if (!userId && !password) {
      showError('errorRequired');
      return false;
    }

    if (!userId) {
      showError('errorUserIdRequired');
      return false;
    }

    if (!password) {
      showError('errorPasswordRequired');
      return false;
    }

    return true;
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    try {
      // アカウントロックチェック
      if (loginAttempts >= maxAttempts) {
        showError('errorAccountLocked');
        return false;
      }

      // ユーザーテーブルから認証
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (!users) {
        showError('errorInvalidCredentials');
        return false;
      }

      const user = users.find(u => 
        u.メールアドレス === userId && 
        u.アクティブフラグ === true
      );

      // 簡易パスワード検証（実際の実装では暗号化されたパスワードと比較）
      const isValidPassword = user && password.length >= 6;

      if (!user || !isValidPassword) {
        loginAttempts++;
        showError('errorInvalidCredentials');
        return false;
      }

      // ログイン成功
      loginAttempts = 0;

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // セッション情報を保存
      const sessionData = {
        userId: user.ユーザーID,
        userName: user.ユーザー名,
        email: user.メールアドレス,
        department: user.所属部署,
        role: user.役職,
        permissionLevel: user.権限レベル,
        approvalAuth: user.承認権限フラグ,
        loginTime: new Date().toISOString()
      };

      if (rememberMe) {
        localStorage.setItem('hybridApprovalSession', JSON.stringify(sessionData));
      } else {
        sessionStorage.setItem('hybridApprovalSession', JSON.stringify(sessionData));
      }

      // ダッシュボードに遷移（実際の実装では適切な画面IDを使用）
      window.location.href = './index.html';
      return true;

    } catch (error) {
      console.error('Login error:', error);
      showError('errorInvalidCredentials');
      return false;
    }
  }

  // フォーム送信
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    if (!validateForm()) {
      return;
    }

    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();
    const rememberMe = rememberMeCheckbox.checked;

    // ローディング状態
    loginButton.disabled = true;
    loginButton.textContent = languages[currentLang].login + '中...';

    const success = await handleLogin(userId, password, rememberMe);

    // ローディング解除
    loginButton.disabled = false;
    loginButton.textContent = languages[currentLang].login;
  });

  // パスワードリセットリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実際の実装では適切なURLを使用）
    window.location.href = './password-reset.html';
  });

  // ヘルプリンク
  helpLink.addEventListener('click', (e) => {
    e.preventDefault();
    // ヘルプページに遷移
    window.open('./help.html', '_blank');
  });

  // 既存のセッションチェック
  const existingSession = localStorage.getItem('hybridApprovalSession') || 
                         sessionStorage.getItem('hybridApprovalSession');

  if (existingSession) {
    try {
      const sessionData = JSON.parse(existingSession);
      // セッションが有効な場合はダッシュボードにリダイレクト
      window.location.href = './index.html';
    } catch (error) {
      // セッションデータが無効な場合はクリア
      localStorage.removeItem('hybridApprovalSession');
      sessionStorage.removeItem('hybridApprovalSession');
    }
  }

  // Enterキーでのログイン
  [userIdInput, passwordInput].forEach(input => {
    input.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        loginForm.dispatchEvent(new Event('submit'));
      }
    });
  });

  // 初期言語設定
  updateLanguage('ja');
}

function(container, apiUrl, tables) {
  let uploadedFiles = [];
  let currentDocumentType = '';

  // DOM要素の取得
  const dropZone = container.querySelector('#drop-zone');
  const fileInput = container.querySelector('#file-input');
  const uploadProgress = container.querySelector('#upload-progress');
  const progressBar = container.querySelector('#progress-bar');
  const uploadedFilesContainer = container.querySelector('#uploaded-files');
  const applicationTitle = container.querySelector('#application-title');
  const applicationDescription = container.querySelector('#application-description');
  const descriptionCount = container.querySelector('#description-count');
  const documentTypeSelect = container.querySelector('#document-type');
  const detectionResult = container.querySelector('#detection-result');
  const detectedType = container.querySelector('#detected-type');
  const confidenceBar = container.querySelector('#confidence-bar');
  const confidenceText = container.querySelector('#confidence-text');
  const lowConfidenceWarning = container.querySelector('#low-confidence-warning');
  const approvalFlow = container.querySelector('#approval-flow');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');
  const btnClear = container.querySelector('#btn-clear');
  const btnRegister = container.querySelector('#btn-register');

  // ファイルアップロード関連
  dropZone.addEventListener('click', () => fileInput.click());

  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--primary)';
    dropZone.style.background = 'rgba(59, 130, 246, 0.1)';
  });

  dropZone.addEventListener('dragleave', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    dropZone.style.background = 'rgba(0,0,0,0.15)';
  });

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    dropZone.style.background = 'rgba(0,0,0,0.15)';
    handleFiles(e.dataTransfer.files);
  });

  fileInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
  });

  // ファイル処理
  function handleFiles(files) {
    Array.from(files).forEach(file => {
      if (validateFile(file)) {
        uploadFile(file);
      }
    });
  }

  function validateFile(file) {
    const allowedTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'];
    const maxSize = 10 * 1024 * 1024; // 10MB

    if (!allowedTypes.includes(file.type)) {
      showError('対応していないファイル形式です。PDF、JPEG、PNG形式のファイルをアップロードしてください。');
      return false;
    }

    if (file.size > maxSize) {
      showError('ファイルサイズが上限（10MB）を超えています。');
      return false;
    }

    return true;
  }

  function uploadFile(file) {
    hideError();
    uploadProgress.style.display = 'block';

    // アップロード進捗のシミュレーション
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        setTimeout(() => {
          uploadProgress.style.display = 'none';
          addUploadedFile(file);
          performDocumentDetection(file);
        }, 500);
      }
      progressBar.style.width = progress + '%';
    }, 200);
  }

  function addUploadedFile(file) {
    const fileId = Date.now() + Math.random();
    uploadedFiles.push({ id: fileId, file: file, detected: false });

    const fileDiv = document.createElement('div');
    fileDiv.id = `file-${fileId}`;
    fileDiv.style.cssText = 'display: flex; align-items: center; justify-content: space-between; padding: 8px 12px; background: rgba(0,0,0,0.15); border-radius: 6px; margin-bottom: 8px;';

    fileDiv.innerHTML = `
      <div style="flex: 1;">
        <div style="font-size: 13px; color: var(--text); font-weight: 500;">${file.name}</div>
        <div style="font-size: 11px; color: var(--text-muted);">${formatFileSize(file.size)} • ${file.type}</div>
      </div>
      <button class="remove-file" data-id="${fileId}" style="background: transparent; border: none; color: var(--text-muted); cursor: pointer; padding: 4px;">✕</button>
    `;

    uploadedFilesContainer.appendChild(fileDiv);
  }

  function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  // 文書種別自動判別
  function performDocumentDetection(file) {
    // 自動判別のシミュレーション
    setTimeout(() => {
      const detectionTypes = [
        { type: 'vacation', name: '休暇申請', confidence: 0.95 },
        { type: 'expense', name: '経費申請', confidence: 0.88 },
        { type: 'purchase', name: '購買申請', confidence: 0.76 },
        { type: 'approval', name: '稟議書', confidence: 0.92 },
        { type: 'overtime', name: '残業申請', confidence: 0.45 }
      ];

      const result = detectionTypes[Math.floor(Math.random() * detectionTypes.length)];
      showDetectionResult(result);
    }, 1500);
  }

  function showDetectionResult(result) {
    currentDocumentType = result.type;
    detectionResult.style.display = 'block';
    detectedType.textContent = result.name;
    confidenceBar.style.width = (result.confidence * 100) + '%';
    confidenceText.textContent = Math.round(result.confidence * 100) + '%';

    // 信頼度が低い場合の警告
    if (result.confidence < 0.7) {
      lowConfidenceWarning.style.display = 'block';
    } else {
      lowConfidenceWarning.style.display = 'none';
    }

    // 文書種別を自動選択
    documentTypeSelect.value = result.type;
    updateApprovalFlow(result.type);
  }

  // 承認フロー更新
  function updateApprovalFlow(docType) {
    const urgency = container.querySelector('input[name="urgency"]:checked').value;

    const flows = {
      vacation: {
        normal: [
          { step: 1, approver: '直属上司', role: '課長', required: true },
          { step: 2, approver: '部門長', role: '部長', required: true }
        ],
        urgent: [
          { step: 1, approver: '部門長', role: '部長', required: true }
        ]
      },
      expense: {
        normal: [
          { step: 1, approver: '直属上司', role: '課長', required: true },
          { step: 2, approver: '経理担当', role: '経理課長', required: true },
          { step: 3, approver: '部門長', role: '部長', required: true }
        ],
        urgent: [
          { step: 1, approver: '経理担当', role: '経理課長', required: true },
          { step: 2, approver: '部門長', role: '部長', required: true }
        ]
      },
      purchase: {
        normal: [
          { step: 1, approver: '直属上司', role: '課長', required: true },
          { step: 2, approver: '購買担当', role: '購買課長', required: true },
          { step: 3, approver: '部門長', role: '部長', required: true }
        ],
        urgent: [
          { step: 1, approver: '購買担当', role: '購買課長', required: true },
          { step: 2, approver: '部門長', role: '部長', required: true }
        ]
      },
      approval: {
        normal: [
          { step: 1, approver: '直属上司', role: '課長', required: true },
          { step: 2, approver: '部門長', role: '部長', required: true },
          { step: 3, approver: '役員', role: '取締役', required: true }
        ],
        urgent: [
          { step: 1, approver: '部門長', role: '部長', required: true },
          { step: 2, approver: '役員', role: '取締役', required: true }
        ]
      },
      overtime: {
        normal: [
          { step: 1, approver: '直属上司', role: '課長', required: true }
        ],
        urgent: [
          { step: 1, approver: '直属上司', role: '課長', required: true }
        ]
      },
      travel: {
        normal: [
          { step: 1, approver: '直属上司', role: '課長', required: true },
          { step: 2, approver: '総務担当', role: '総務課長', required: true },
          { step: 3, approver: '部門長', role: '部長', required: true }
        ],
        urgent: [
          { step: 1, approver: '総務担当', role: '総務課長', required: true },
          { step: 2, approver: '部門長', role: '部長', required: true }
        ]
      }
    };

    if (!docType || !flows[docType]) {
      approvalFlow.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">文書種別を選択すると承認フローが表示されます</div>';
      return;
    }

    const flow = flows[docType][urgency];
    let flowHtml = '';

    if (urgency === 'urgent') {
      flowHtml += '<div style="background: rgba(245, 158, 11, 0.1); border: 1px solid rgba(245, 158, 11, 0.3); border-radius: 4px; padding: 6px 8px; margin-bottom: 12px; font-size: 11px; color: #fbbf24;">🚨 緊急申請フロー</div>';
    }

    flow.forEach((step, index) => {
      const isLast = index === flow.length - 1;
      flowHtml += `
        <div style="display: flex; align-items: center; margin-bottom: ${isLast ? '0' : '8px'};">
          <div style="width: 20px; height: 20px; background: var(--primary); color: #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 600; margin-right: 8px;">${step.step}</div>
          <div style="flex: 1;">
            <div style="font-size: 12px; color: var(--text); font-weight: 500;">${step.approver}</div>
            <div style="font-size: 10px; color: var(--text-muted);">${step.role}</div>
          </div>
        </div>
        ${!isLast ? '<div style="width: 2px; height: 12px; background: rgba(255,255,255,0.18); margin-left: 10px; margin-bottom: 8px;"></div>' : ''}
      `;
    });

    approvalFlow.innerHTML = flowHtml;
  }

  // 文字数カウント
  applicationDescription.addEventListener('input', () => {
    descriptionCount.textContent = applicationDescription.value.length;
  });

  // 文書種別手動選択
  documentTypeSelect.addEventListener('change', (e) => {
    if (e.target.value) {
      updateApprovalFlow(e.target.value);
    }
  });

  // 緊急度変更
  container.addEventListener('change', (e) => {
    if (e.target.name === 'urgency') {
      const selectedType = documentTypeSelect.value;
      if (selectedType) {
        updateApprovalFlow(selectedType);
      }
    }
  });

  // ファイル削除
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.remove-file');
    if (removeBtn) {
      const fileId = removeBtn.dataset.id;
      uploadedFiles = uploadedFiles.filter(f => f.id != fileId);
      container.querySelector(`#file-${fileId}`).remove();

      if (uploadedFiles.length === 0) {
        detectionResult.style.display = 'none';
        documentTypeSelect.value = '';
        approvalFlow.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">文書種別を選択すると承認フローが表示されます</div>';
      }
    }
  });

  // クリアボタン
  btnClear.addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      applicationTitle.value = '';
      applicationDescription.value = '';
      descriptionCount.textContent = '0';
      documentTypeSelect.value = '';
      container.querySelector('input[name="urgency"][value="normal"]').checked = true;
      uploadedFiles = [];
      uploadedFilesContainer.innerHTML = '';
      detectionResult.style.display = 'none';
      approvalFlow.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">文書種別を選択すると承認フローが表示されます</div>';
      hideError();
    }
  });

  // 申請登録ボタン
  btnRegister.addEventListener('click', async () => {
    if (!validateForm()) return;

    const urgency = container.querySelector('input[name="urgency"]:checked').value;
    const docType = documentTypeSelect.value;

    if (!docType) {
      showError('文書種別を選択してください。');
      return;
    }

    if (uploadedFiles.length === 0) {
      showError('申請書類をアップロードしてください。');
      return;
    }

    const applicationData = {
      申請者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      申請種別: docType,
      申請タイトル: applicationTitle.value,
      申請内容: applicationDescription.value,
      承認状態: '申請中',
      承認段階: 1,
      緊急フラグ: urgency === 'urgent',
      添付ファイル有無: uploadedFiles.length > 0,
      作成者ID: 'current-user-id'
    };

    try {
      const saved = await window.aivicApi.save(1, applicationData); // 申請書類テーブル
      if (saved) {
        alert('申請書類が正常に登録されました。');
        // 文書種別判定画面に遷移
        window.showScreen("scr-1779422563059");
      }
    } catch (error) {
      showError('申請の登録に失敗しました。もう一度お試しください。');
    }
  });

  function validateForm() {
    hideError();

    if (!applicationTitle.value.trim()) {
      showError('申請タイトルを入力してください。');
      applicationTitle.focus();
      return false;
    }

    if (!applicationDescription.value.trim()) {
      showError('申請内容説明を入力してください。');
      applicationDescription.focus();
      return false;
    }

    return true;
  }

  function showError(message) {
    errorText.textContent = message;
    errorMessage.style.display = 'block';
    errorMessage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  function hideError() {
    errorMessage.style.display = 'none';
  }
}

function(container, apiUrl, tables) {
  let allApplications = [];
  let allUsers = [];
  let allRoutes = [];
  let sortColumn = null;
  let sortDirection = 'asc';

  // ユーザー情報とルート情報を取得
  async function loadRelatedData() {
    try {
      allUsers = await window.aivicApi.list(0) || []; // ユーザー
      allRoutes = await window.aivicApi.list(7) || []; // 処理ルート
    } catch (error) {
      console.error('関連データの取得に失敗:', error);
    }
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = allUsers.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : '';
  }

  // 優先度ラベルを取得
  function getPriorityLabel(priority) {
    const labels = { 1: '低', 2: '通常', 3: '高', 4: '緊急' };
    return labels[priority] || '通常';
  }

  // 優先度の色を取得
  function getPriorityColor(priority) {
    const colors = {
      1: '#6b7280',
      2: '#3b82f6',
      3: '#f59e0b',
      4: '#ef4444'
    };
    return colors[priority] || '#3b82f6';
  }

  // 進捗率を計算
  function calculateProgress(applicationId) {
    const route = allRoutes.find(r => r.申請書類ID === applicationId);
    if (!route) return 0;

    // 簡易的な進捗計算（実際の承認ステップ数に基づく）
    const totalSteps = 3; // 仮定
    const currentStep = route.現在ステップ番号 || 1;

    if (route.処理状況 === '承認済み') return 100;
    if (route.処理状況 === '却下' || route.処理状況 === '取下げ') return 0;

    return Math.min(Math.round((currentStep / totalSteps) * 100), 90);
  }

  // 遅延日数を計算
  function calculateDelayDays(createdAt, status) {
    if (status === '承認済' || status === '却下' || status === '取下げ') return 0;

    const created = new Date(createdAt);
    const now = new Date();
    const diffTime = now - created;
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    // 3日を超えたら遅延とみなす
    return Math.max(0, diffDays - 3);
  }

  // 進捗バーを生成
  function createProgressBar(progress, status) {
    const color = status === '承認済' ? '#10b981' : 
                  status === '却下' ? '#ef4444' : 
                  progress > 0 ? '#3b82f6' : '#6b7280';

    return `
      <div style="width: 80px; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; position: relative;">
        <div style="width: ${progress}%; height: 100%; background: ${color}; border-radius: 3px; transition: width 0.3s;"></div>
      </div>
      <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${progress}%</div>
    `;
  }

  // テーブル行を再描画
  function renderRows(applications) {
    const tbody = container.querySelector('#applications-tbody');
    const noDataMessage = container.querySelector('#no-data-message');
    const recordCount = container.querySelector('#record-count');

    recordCount.textContent = applications.length;

    if (applications.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.style.display = 'block';
      return;
    }

    noDataMessage.style.display = 'none';

    tbody.innerHTML = applications.map(app => {
      const applicantName = getUserName(app.申請者ID);
      const currentApproverName = getUserName(app.現在承認者ID);
      const progress = calculateProgress(app.申請書類ID);
      const delayDays = calculateDelayDays(app.作成日時, app.承認状態);
      const isDelayed = delayDays > 0;
      const priorityColor = getPriorityColor(app.優先度 || 2);

      const rowStyle = isDelayed ? 'background: rgba(239, 68, 68, 0.05); border-left: 3px solid #ef4444;' : '';

      return `
        <tr data-id="${app.申請書類ID}" style="${rowStyle}">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.申請書類ID?.substring(0, 8) || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${applicantName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.申請種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.申請タイトル || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.作成日時 ? new Date(app.作成日時).toLocaleDateString() : ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${app.承認状態 === '承認済' ? 'rgba(16, 185, 129, 0.2)' : app.承認状態 === '却下' ? 'rgba(239, 68, 68, 0.2)' : 'rgba(59, 130, 246, 0.2)'}; color: var(--text);">
              ${app.承認状態 || '申請中'}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${currentApproverName}</td>
          <td style="padding: 6px 10px;">${createProgressBar(progress, app.承認状態)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: rgba(${priorityColor === '#ef4444' ? '239, 68, 68' : priorityColor === '#f59e0b' ? '245, 158, 11' : priorityColor === '#3b82f6' ? '59, 130, 246' : '107, 114, 128'}, 0.2); color: var(--text);">
              ${getPriorityLabel(app.優先度 || 2)}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: ${isDelayed ? '#ef4444' : 'var(--text)'};">
            ${isDelayed ? `${delayDays}日` : '-'}
            ${isDelayed ? '<span style="margin-left: 4px;">⚠️</span>' : ''}
          </td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary detail-btn" data-id="${app.申請書類ID}" style="font-size: 11px; padding: 4px 8px;">案件詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // フィルター処理
  function applyFilters() {
    const documentType = container.querySelector('#filter-document-type').value;
    const approvalStatus = container.querySelector('#filter-approval-status').value;
    const applicantName = container.querySelector('#search-applicant').value.trim();
    const approverName = container.querySelector('#search-approver').value.trim();
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const errorMessage = container.querySelector('#error-message');

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      errorMessage.textContent = '開始日は終了日より前の日付を入力してください';
      errorMessage.style.display = 'block';
      return;
    }

    errorMessage.style.display = 'none';

    let filtered = allApplications.filter(app => {
      // 文書種別フィルター
      if (documentType && app.申請種別 !== documentType) return false;

      // 承認状況フィルター
      if (approvalStatus && app.承認状態 !== approvalStatus) return false;

      // 申請者名検索
      if (applicantName) {
        const userName = getUserName(app.申請者ID);
        if (!userName.includes(applicantName)) return false;
      }

      // 承認者名検索
      if (approverName) {
        const currentApproverName = getUserName(app.現在承認者ID);
        if (!currentApproverName.includes(approverName)) return false;
      }

      // 申請日期間フィルター
      if (startDate || endDate) {
        const appDate = new Date(app.作成日時);
        if (startDate && appDate < new Date(startDate)) return false;
        if (endDate && appDate > new Date(endDate + 'T23:59:59')) return false;
      }

      return true;
    });

    // 特殊文字チェック
    const specialChars = /<script|javascript:|on\w+=/i;
    if (specialChars.test(applicantName) || specialChars.test(approverName)) {
      errorMessage.textContent = '不正な文字が含まれています';
      errorMessage.style.display = 'block';
      return;
    }

    // ソート適用
    if (sortColumn) {
      filtered.sort((a, b) => {
        let aVal = a[sortColumn];
        let bVal = b[sortColumn];

        if (sortColumn === '優先度') {
          aVal = a.優先度 || 2;
          bVal = b.優先度 || 2;
        }

        if (typeof aVal === 'string') {
          aVal = aVal.toLowerCase();
          bVal = bVal.toLowerCase();
        }

        if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
        return 0;
      });
    }

    renderRows(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['申請ID', '申請者', '申請種別', '申請タイトル', '申請日', '承認状態', '現在承認者', '進捗率', '優先度', '遅延日数'];
    const rows = allApplications.map(app => [
      app.申請書類ID?.substring(0, 8) || '',
      getUserName(app.申請者ID),
      app.申請種別 || '',
      app.申請タイトル || '',
      app.作成日時 ? new Date(app.作成日時).toLocaleDateString() : '',
      app.承認状態 || '申請中',
      getUserName(app.現在承認者ID),
      calculateProgress(app.申請書類ID) + '%',
      getPriorityLabel(app.優先度 || 2),
      calculateDelayDays(app.作成日時, app.承認状態) + '日'
    ]);

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `承認フロー進捗_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  async function initialize() {
    await loadRelatedData();

    try {
      allApplications = await window.aivicApi.list(1) || tables[1]?.records || [];
    } catch (error) {
      console.error('申請データの取得に失敗:', error);
      allApplications = tables[1]?.records || [];
    }

    renderRows(allApplications);
  }

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#filter-document-type').value = '';
    container.querySelector('#filter-approval-status').value = '';
    container.querySelector('#search-applicant').value = '';
    container.querySelector('#search-approver').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#error-message').style.display = 'none';
    renderRows(allApplications);
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-delay-check').addEventListener('click', () => {
    window.showScreen("scr-1779422271790");
  });

  container.querySelector('#btn-route-change').addEventListener('click', () => {
    window.showScreen("scr-1779422283293");
  });

  // ソート機能
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('[data-sort]');
    if (sortHeader) {
      const column = sortHeader.dataset.sort;
      if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        sortColumn = column;
        sortDirection = 'asc';
      }
      applyFilters();
    }

    // 案件詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen("scr-1779422369173");
    }
  });

  // ネットワークエラーハンドリング
  window.addEventListener('offline', () => {
    const errorMessage = container.querySelector('#error-message');
    errorMessage.textContent = 'ネットワークに接続できません。接続を確認してから再試行してください。';
    errorMessage.style.display = 'block';
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  let selectedApplication = null;
  let currentRoute = null;
  let newRoute = null;
  let isConfirmed = false;

  // DOM要素の取得
  const applicationSelect = container.querySelector('#application-select');
  const currentRouteDisplay = container.querySelector('#current-route-display');
  const newRouteSelect = container.querySelector('#new-route-select');
  const approvalStepsDisplay = container.querySelector('#approval-steps-display');
  const changeReasonTextarea = container.querySelector('#change-reason');
  const reasonCharCount = container.querySelector('#reason-char-count');
  const notificationMessage = container.querySelector('#notification-message');
  const messageCharCount = container.querySelector('#message-char-count');
  const errorMessage = container.querySelector('#error-message');
  const successMessage = container.querySelector('#success-message');
  const confirmationModal = container.querySelector('#confirmation-modal');
  const confirmationContent = container.querySelector('#confirmation-content');

  // ボタン要素
  const changeApproverBtn = container.querySelector('#change-approver-btn');
  const selectAllBtn = container.querySelector('#select-all-btn');
  const deselectAllBtn = container.querySelector('#deselect-all-btn');
  const confirmChangeBtn = container.querySelector('#confirm-change-btn');
  const executeChangeBtn = container.querySelector('#execute-change-btn');
  const sendNotificationBtn = container.querySelector('#send-notification-btn');
  const routeUpdateBtn = container.querySelector('#route-update-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const modalCancelBtn = container.querySelector('#modal-cancel-btn');
  const modalConfirmBtn = container.querySelector('#modal-confirm-btn');

  // エラー・成功メッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    successMessage.style.display = 'none';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  function showSuccess(message) {
    successMessage.textContent = message;
    successMessage.style.display = 'block';
    errorMessage.style.display = 'none';
    setTimeout(() => {
      successMessage.style.display = 'none';
    }, 5000);
  }

  // 文字数カウント更新
  function updateCharCount() {
    reasonCharCount.textContent = changeReasonTextarea.value.length;
    messageCharCount.textContent = notificationMessage.value.length;
  }

  // 申請書類選択時の処理
  applicationSelect.addEventListener('change', async function() {
    const selectedId = this.value;
    if (!selectedId) {
      currentRouteDisplay.textContent = '申請書類を選択してください';
      selectedApplication = null;
      return;
    }

    try {
      const applications = await window.aivicApi.list(1); // 申請書類テーブル
      selectedApplication = applications.find(app => app.id === selectedId);

      if (selectedApplication) {
        // 現在の処理ルート表示
        const routes = await window.aivicApi.list(7); // 処理ルートテーブル
        currentRoute = routes.find(route => route.申請書類ID === selectedId);

        if (currentRoute) {
          currentRouteDisplay.innerHTML = `
            <div><strong>申請種別:</strong> ${selectedApplication.申請種別}</div>
            <div><strong>現在の承認者:</strong> ${selectedApplication.現在承認者ID || '未設定'}</div>
            <div><strong>承認段階:</strong> ${selectedApplication.承認段階}段階目</div>
            <div><strong>処理状況:</strong> ${currentRoute.処理状況}</div>
          `;
        }
      }
    } catch (error) {
      showError('申請書類の詳細取得に失敗しました');
    }
  });

  // 新しい処理ルート選択時の処理
  newRouteSelect.addEventListener('change', function() {
    const selectedRoute = this.value;
    newRoute = selectedRoute;

    if (!selectedRoute) {
      approvalStepsDisplay.textContent = '処理ルートを選択してください';
      return;
    }

    // 承認ステップ表示（サンプルデータ）
    const routeSteps = {
      'route1': [
        { step: 1, approver: '課長（田中課長）', required: true },
        { step: 2, approver: '部長（佐藤部長）', required: true },
        { step: 3, approver: '役員（山田役員）', required: true }
      ],
      'route2': [
        { step: 1, approver: '役員（山田役員）', required: true }
      ],
      'route3': [
        { step: 1, approver: '委員会（承認委員会）', required: true },
        { step: 2, approver: '役員（山田役員）', required: true }
      ],
      'route4': [
        { step: 1, approver: '課長（田中課長）', required: true }
      ]
    };

    const steps = routeSteps[selectedRoute] || [];
    approvalStepsDisplay.innerHTML = steps.map(step => 
      `<div style="margin-bottom: 4px;">
        <strong>ステップ${step.step}:</strong> ${step.approver} 
        ${step.required ? '<span style="color: #ef4444;">(必須)</span>' : '<span style="color: var(--text-muted);">(任意)</span>'}
      </div>`
    ).join('');

    // 同一ルート選択チェック
    if (currentRoute && selectedRoute === currentRoute.承認フロー定義ID) {
      showError('現在と同じ処理ルートが選択されています。変更する必要がありますか？');
    }
  });

  // 承認者変更ボタン
  changeApproverBtn.addEventListener('click', function() {
    if (!selectedApplication) {
      showError('申請書類を選択してください');
      return;
    }
    // 承認者変更の詳細画面への遷移などの処理
    showSuccess('承認者変更画面を開きます');
  });

  // 全選択・全解除
  selectAllBtn.addEventListener('click', function() {
    const checkboxes = container.querySelectorAll('#notification-targets input[type="checkbox"]');
    checkboxes.forEach(cb => cb.checked = true);
  });

  deselectAllBtn.addEventListener('click', function() {
    const checkboxes = container.querySelectorAll('#notification-targets input[type="checkbox"]');
    checkboxes.forEach(cb => cb.checked = false);
  });

  // 変更内容確認
  confirmChangeBtn.addEventListener('click', function() {
    if (!selectedApplication) {
      showError('申請書類を選択してください');
      return;
    }
    if (!newRoute) {
      showError('新しい処理ルートを選択してください');
      return;
    }
    if (!changeReasonTextarea.value.trim()) {
      showError('変更理由を入力してください');
      return;
    }

    // 確認モーダル表示
    confirmationContent.innerHTML = `
      <div><strong>申請書類:</strong> ${selectedApplication.申請タイトル}</div>
      <div><strong>申請者:</strong> ${selectedApplication.申請者ID}</div>
      <div><strong>新しい処理ルート:</strong> ${newRouteSelect.options[newRouteSelect.selectedIndex].text}</div>
      <div><strong>変更理由:</strong> ${changeReasonTextarea.value}</div>
    `;
    confirmationModal.style.display = 'flex';
  });

  // モーダル操作
  modalCancelBtn.addEventListener('click', function() {
    confirmationModal.style.display = 'none';
  });

  modalConfirmBtn.addEventListener('click', function() {
    confirmationModal.style.display = 'none';
    isConfirmed = true;
    executeChangeBtn.disabled = false;
    showSuccess('変更内容が確認されました。変更実行ボタンが有効になりました。');
  });

  // 処理ルート変更実行
  executeChangeBtn.addEventListener('click', async function() {
    if (!isConfirmed) {
      showError('変更内容を確認してください');
      return;
    }

    try {
      // 処理ルート更新
      const updateData = {
        申請書類ID: selectedApplication.id,
        承認フロー定義ID: newRoute,
        処理状況: '承認待ち',
        更新日時: new Date().toISOString(),
        更新者ID: 'current-user-id'
      };

      await window.aivicApi.update(7, currentRoute.id, updateData);

      // 承認履歴に記録
      const historyData = {
        申請書類ID: selectedApplication.id,
        承認ステップID: 'new-step-id',
        承認者ID: 'current-user-id',
        承認結果: '処理ルート変更',
        承認コメント: changeReasonTextarea.value,
        承認日時: new Date().toISOString(),
        承認順序: 1,
        代理承認フラグ: false
      };

      await window.aivicApi.save(4, historyData);

      showSuccess('処理ルートの変更が完了しました');
      isConfirmed = false;
      executeChangeBtn.disabled = true;
    } catch (error) {
      showError('処理ルートの変更に失敗しました');
    }
  });

  // 通知送信
  sendNotificationBtn.addEventListener('click', async function() {
    const selectedTargets = Array.from(container.querySelectorAll('#notification-targets input[type="checkbox"]:checked'));

    if (selectedTargets.length === 0) {
      showError('通知対象者を選択してください');
