    }

    if (!notificationMessage.value.trim()) {
      showError('通知メッセージを入力してください');
      return;
    }

    try {
      // 各対象者に通知履歴を作成
      for (const target of selectedTargets) {
        const notificationData = {
          申請書類ID: selectedApplication?.id || null,
          通知対象ユーザーID: target.value,
          通知種別: '処理ルート変更',
          通知タイトル: '処理ルート変更のお知らせ',
          通知内容: notificationMessage.value,
          送信方法: 'システム内通知',
          送信状態: '送信完了',
          送信日時: new Date().toISOString(),
          既読フラグ: false,
          再送回数: 0,
          作成日時: new Date().toISOString(),
          作成者ID: 'current-user-id'
        };

        await window.aivicApi.save(5, notificationData);
      }

      showSuccess(`${selectedTargets.length}名に通知を送信しました`);
    } catch (error) {
      showError('通知送信に失敗しました');
    }
  });

  // ルート更新ボタン（画面遷移）
  routeUpdateBtn.addEventListener('click', function() {
    window.showScreen("scr-1779422546501");
  });

  // キャンセル
  cancelBtn.addEventListener('click', function() {
    if (confirm('入力内容がクリアされますが、よろしいですか？')) {
      applicationSelect.value = '';
      newRouteSelect.value = '';
      changeReasonTextarea.value = '';
      notificationMessage.value = '';
      currentRouteDisplay.textContent = '申請書類を選択してください';
      approvalStepsDisplay.textContent = '処理ルートを選択してください';

      const checkboxes = container.querySelectorAll('#notification-targets input[type="checkbox"]');
      checkboxes.forEach(cb => cb.checked = false);

      selectedApplication = null;
      currentRoute = null;
      newRoute = null;
      isConfirmed = false;
      executeChangeBtn.disabled = true;

      updateCharCount();
      showSuccess('入力内容をクリアしました');
    }
  });

  // 文字数カウント更新イベント
  changeReasonTextarea.addEventListener('input', updateCharCount);
  notificationMessage.addEventListener('input', updateCharCount);

  // 初期化
  updateCharCount();

  // モーダル外クリックで閉じる
  confirmationModal.addEventListener('click', function(e) {
    if (e.target === confirmationModal) {
      confirmationModal.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  let currentTab = 'approval';
  let currentSort = { field: null, direction: 'asc' };
  let allApprovalData = [];
  let allNotificationData = [];

  // 再描画関数の定義
  function renderApprovalRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.承認履歴ID || r.id || ''}">
        <td>${r.承認日時 || ''}</td>
        <td>${r.申請書類ID || ''}</td>
        <td>${r.文書種別 || ''}</td>
        <td>${r.申請者名 || ''}</td>
        <td>${r.承認者名 || ''}</td>
        <td><span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${getStatusColor(r.承認結果)};">${r.承認結果 || ''}</span></td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis;">${r.承認コメント || ''}</td>
        <td><button class="action-btn secondary detail-btn" data-id="${r.承認履歴ID || r.id || ''}" style="font-size: 11px; padding: 4px 8px;">詳細</button></td>
      </tr>
    `).join('');
  }

  function renderNotificationRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.通知履歴ID || r.id || ''}">
        <td>${r.送信日時 || ''}</td>
        <td>${r.申請書類ID || ''}</td>
        <td>${r.通知種別 || ''}</td>
        <td>${r.通知対象者名 || ''}</td>
        <td>${r.送信方法 || ''}</td>
        <td><span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${getNotificationStatusColor(r.送信状態)};">${r.送信状態 || ''}</span></td>
        <td>${r.既読フラグ ? '既読' : '未読'}</td>
        <td><button class="action-btn secondary detail-btn" data-id="${r.通知履歴ID || r.id || ''}" style="font-size: 11px; padding: 4px 8px;">詳細</button></td>
      </tr>
    `).join('');
  }

  function getStatusColor(status) {
    switch(status) {
      case '承認済み': return 'rgba(34, 197, 94, 0.2)';
      case '却下': return 'rgba(239, 68, 68, 0.2)';
      case '保留中': return 'rgba(251, 191, 36, 0.2)';
      case '承認待ち': return 'rgba(59, 130, 246, 0.2)';
      default: return 'rgba(156, 163, 175, 0.2)';
    }
  }

  function getNotificationStatusColor(status) {
    switch(status) {
      case '送信完了': return 'rgba(34, 197, 94, 0.2)';
      case '送信失敗': return 'rgba(239, 68, 68, 0.2)';
      case '送信中': return 'rgba(251, 191, 36, 0.2)';
      case '送信待ち': return 'rgba(156, 163, 175, 0.2)';
      default: return 'rgba(156, 163, 175, 0.2)';
    }
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const approvalData = await window.aivicApi.list(4); // 承認履歴テーブル
      const notificationData = await window.aivicApi.list(5); // 通知履歴テーブル

      if (approvalData) {
        allApprovalData = approvalData;
      } else {
        allApprovalData = tables[4]?.records || [];
      }

      if (notificationData) {
        allNotificationData = notificationData;
      } else {
        allNotificationData = tables[5]?.records || [];
      }

      if (currentTab === 'approval') {
        renderApprovalRows(allApprovalData);
      } else {
        renderNotificationRows(allNotificationData);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      allApprovalData = tables[4]?.records || [];
      allNotificationData = tables[5]?.records || [];
      if (currentTab === 'approval') {
        renderApprovalRows(allApprovalData);
      } else {
        renderNotificationRows(allNotificationData);
      }
    }
  }

  // タブ切り替え
  function switchTab(tabType) {
    currentTab = tabType;

    // タブの見た目更新
    const approvalTab = container.querySelector('#tab-approval');
    const notificationTab = container.querySelector('#tab-notification');
    const approvalHeader = container.querySelector('#approval-header');
    const notificationHeader = container.querySelector('#notification-header');
    const notificationTypeFilter = container.querySelector('#notification-type-filter');

    if (tabType === 'approval') {
      approvalTab.style.color = 'var(--primary)';
      approvalTab.style.borderBottomColor = 'var(--primary)';
      notificationTab.style.color = 'var(--text-muted)';
      notificationTab.style.borderBottomColor = 'transparent';
      approvalHeader.style.display = '';
      notificationHeader.style.display = 'none';
      notificationTypeFilter.style.display = 'none';
      renderApprovalRows(allApprovalData);
    } else {
      notificationTab.style.color = 'var(--primary)';
      notificationTab.style.borderBottomColor = 'var(--primary)';
      approvalTab.style.color = 'var(--text-muted)';
      approvalTab.style.borderBottomColor = 'transparent';
      approvalHeader.style.display = 'none';
      notificationHeader.style.display = '';
      notificationTypeFilter.style.display = 'block';
      renderNotificationRows(allNotificationData);
    }
  }

  // 検索処理
  function performSearch() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const documentNumber = container.querySelector('#document-number').value.trim();
    const documentType = container.querySelector('#document-type').value;
    const approverName = container.querySelector('#approver-name').value.trim();
    const approvalStatus = container.querySelector('#approval-status').value;
    const notificationType = container.querySelector('#notification-type').value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください。');
      return;
    }

    // 申請書類番号バリデーション
    if (documentNumber && !/^[A-Za-z0-9\-_]+$/.test(documentNumber)) {
      showError('有効な申請書類番号を入力してください。');
      return;
    }

    hideError();

    let filteredData;
    if (currentTab === 'approval') {
      filteredData = allApprovalData.filter(row => {
        if (startDate && row.承認日時 && new Date(row.承認日時) < new Date(startDate)) return false;
        if (endDate && row.承認日時 && new Date(row.承認日時) > new Date(endDate)) return false;
        if (documentNumber && !row.申請書類ID?.includes(documentNumber)) return false;
        if (documentType && row.文書種別 !== documentType) return false;
        if (approverName && !row.承認者名?.includes(approverName)) return false;
        if (approvalStatus && row.承認結果 !== approvalStatus) return false;
        return true;
      });
      renderApprovalRows(filteredData);
    } else {
      filteredData = allNotificationData.filter(row => {
        if (startDate && row.送信日時 && new Date(row.送信日時) < new Date(startDate)) return false;
        if (endDate && row.送信日時 && new Date(row.送信日時) > new Date(endDate)) return false;
        if (documentNumber && !row.申請書類ID?.includes(documentNumber)) return false;
        if (notificationType && row.通知種別 !== notificationType) return false;
        return true;
      });
      renderNotificationRows(filteredData);
    }

    if (filteredData.length === 0) {
      showError('検索条件に該当するデータが見つかりませんでした。');
    }
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
  }

  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.style.display = 'none';
  }

  // ソート処理
  function sortData(field) {
    if (currentSort.field === field) {
      currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
    } else {
      currentSort.field = field;
      currentSort.direction = 'asc';
    }

    const data = currentTab === 'approval' ? allApprovalData : allNotificationData;
    const sortedData = [...data].sort((a, b) => {
      const aVal = a[field] || '';
      const bVal = b[field] || '';

      if (currentSort.direction === 'asc') {
        return aVal.localeCompare(bVal);
      } else {
        return bVal.localeCompare(aVal);
      }
    });

    if (currentTab === 'approval') {
      allApprovalData = sortedData;
      renderApprovalRows(sortedData);
    } else {
      allNotificationData = sortedData;
      renderNotificationRows(sortedData);
    }

    // ソートアイコン更新
    const icon = currentTab === 'approval' ? 
      container.querySelector('#sort-icon') : 
      container.querySelector('#sort-icon-notif');
    if (icon) {
      icon.textContent = currentSort.direction === 'asc' ? '↑' : '↓';
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const data = currentTab === 'approval' ? allApprovalData : allNotificationData;
    let headers, rows;

    if (currentTab === 'approval') {
      headers = ['処理日時', '申請書類番号', '文書種別', '申請者', '承認者', '承認結果', 'コメント'];
      rows = data.map(r => [
        r.承認日時 || '',
        r.申請書類ID || '',
        r.文書種別 || '',
        r.申請者名 || '',
        r.承認者名 || '',
        r.承認結果 || '',
        r.承認コメント || ''
      ]);
    } else {
      headers = ['送信日時', '申請書類番号', '通知種別', '通知対象者', '送信方法', '送信状態', '既読状況'];
      rows = data.map(r => [
        r.送信日時 || '',
        r.申請書類ID || '',
        r.通知種別 || '',
        r.通知対象者名 || '',
        r.送信方法 || '',
        r.送信状態 || '',
        r.既読フラグ ? '既読' : '未読'
      ]);
    }

    const csvContent = '\uFEFF' + [headers, ...rows]
      .map(row => row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(','))
      .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `${currentTab === 'approval' ? '承認履歴' : '通知履歴'}_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー登録
  container.querySelector('#tab-approval').addEventListener('click', () => switchTab('approval'));
  container.querySelector('#tab-notification').addEventListener('click', () => switchTab('notification'));

  container.querySelector('#btn-search').addEventListener('click', performSearch);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#document-number').value = '';
    container.querySelector('#document-type').value = '';
    container.querySelector('#approver-name').value = '';
    container.querySelector('#approval-status').value = '';
    container.querySelector('#notification-type').value = '';
    hideError();

    if (currentTab === 'approval') {
      renderApprovalRows(allApprovalData);
    } else {
      renderNotificationRows(allNotificationData);
    }
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // ソートイベント
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('[data-sort]');
    if (sortHeader) {
      const field = sortHeader.dataset.sort;
      sortData(field);
    }

    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      if (currentTab === 'approval') {
        window.showScreen('scr-1779422434952'); // 申請書類確認画面
      } else {
        window.showScreen('scr-1779422407913'); // 承認案件通知画面
      }
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let selectedFiles = [];
  let currentUserId = null;

  // 現在のユーザー情報を取得
  async function loadCurrentUser() {
    try {
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (users && users.length > 0) {
        currentUserId = users[0].id;
        const applicantNameInput = container.querySelector('#applicant-name');
        applicantNameInput.value = users[0].ユーザー名 || users[0].userName || '';
      }
    } catch (error) {
      console.error('ユーザー情報の取得に失敗しました:', error);
    }
  }

  // 今日の日付を設定
  function setTodayDate() {
    const today = new Date().toISOString().split('T')[0];
    container.querySelector('#application-date').value = today;
  }

  // 文字数カウンター更新
  function updateCounter(textareaId, counterId, maxLength) {
    const textarea = container.querySelector(`#${textareaId}`);
    const counter = container.querySelector(`#${counterId}`);
    const currentLength = textarea.value.length;
    counter.textContent = `${currentLength}/${maxLength}`;

    if (currentLength > maxLength) {
      counter.style.color = '#ff6a00';
    } else {
      counter.style.color = 'var(--text-muted)';
    }
  }

  // ファイルアップロード処理
  function handleFileUpload(files) {
    const fileError = container.querySelector('#file-error');
    const allowedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx', '.jpg', '.jpeg', '.png'];
    const maxSize = 10 * 1024 * 1024; // 10MB

    for (let file of files) {
      const extension = '.' + file.name.split('.').pop().toLowerCase();

      if (!allowedTypes.includes(extension)) {
        fileError.textContent = 'サポートされていないファイル形式です。PDF、Word、Excel、画像ファイル（JPG、PNG）のみアップロード可能です。';
        fileError.style.display = 'block';
        return;
      }

      if (file.size > maxSize) {
        fileError.textContent = 'ファイルサイズが上限（10MB）を超えています。';
        fileError.style.display = 'block';
        return;
      }

      selectedFiles.push(file);
    }

    fileError.style.display = 'none';
    updateFileList();
  }

  // ファイルリスト表示更新
  function updateFileList() {
    const fileList = container.querySelector('#file-list');
    fileList.innerHTML = selectedFiles.map((file, index) => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 4px 8px; background: rgba(0,0,0,0.15); border-radius: 4px; margin-bottom: 4px;">
        <span style="font-size: 12px; color: var(--text);">${file.name} (${(file.size / 1024).toFixed(1)}KB)</span>
        <button type="button" class="remove-file" data-index="${index}" style="background: none; border: none; color: #ff6a00; cursor: pointer; font-size: 12px;">削除</button>
      </div>
    `).join('');
  }

  // バリデーション
  function validateForm() {
    let isValid = true;
    const errors = {};

    // 必須項目チェック
    const title = container.querySelector('#application-title').value.trim();
    if (!title) {
      errors.title = '申請書類タイトルは必須です。';
      isValid = false;
    } else if (title.length > 100) {
      errors.title = '申請書類タイトルは100文字以内で入力してください。';
      isValid = false;
    }

    const documentType = container.querySelector('#document-type').value;
    if (!documentType) {
      errors.documentType = '文書種別を選択してください。';
      isValid = false;
    }

    const applicationDate = container.querySelector('#application-date').value;
    if (!applicationDate) {
      errors.date = '申請日付を選択してください。';
      isValid = false;
    } else {
      const selectedDate = new Date(applicationDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (selectedDate < today) {
        errors.date = '過去の日付は選択できません。';
        isValid = false;
      }
    }

    const content = container.querySelector('#application-content').value.trim();
    if (!content) {
      errors.content = '申請内容詳細は必須です。';
      isValid = false;
    } else if (content.length > 2000) {
      errors.content = '申請内容詳細は2000文字以内で入力してください。';
      isValid = false;
    }

    const approvalFlow = container.querySelector('#approval-flow').value;
    if (!approvalFlow) {
      errors.approvalFlow = '承認フローを選択してください。';
      isValid = false;
    }

    const urgency = container.querySelector('input[name="urgency"]:checked');
    if (!urgency) {
      errors.urgency = '緊急度を選択してください。';
      isValid = false;
    }

    // 申請金額チェック
    const amount = container.querySelector('#application-amount').value;
    if (amount && (isNaN(amount) || parseFloat(amount) < 0)) {
      errors.amount = '申請金額は正の数値を入力してください。';
      isValid = false;
    }

    // 申請理由文字数チェック
    const reason = container.querySelector('#application-reason').value;
    if (reason.length > 1000) {
      errors.reason = '申請理由は1000文字以内で入力してください。';
      isValid = false;
    }

    // エラー表示
    Object.keys(errors).forEach(key => {
      const errorElement = container.querySelector(`#${key}-error`);
      if (errorElement) {
        errorElement.textContent = errors[key];
        errorElement.style.display = 'block';
      }
    });

    // エラーがない項目のエラー表示をクリア
    const errorElements = container.querySelectorAll('.error-message');
    errorElements.forEach(el => {
      const fieldName = el.id.replace('-error', '');
      if (!errors[fieldName]) {
        el.style.display = 'none';
      }
    });

    return isValid;
  }

  // フォームデータ収集
  function collectFormData(isDraft = false) {
    const urgencyElement = container.querySelector('input[name="urgency"]:checked');
    const subsidyRelations = Array.from(container.querySelectorAll('input[name="subsidyRelation"]:checked')).map(cb => cb.value);
    const relatedDepartments = Array.from(container.querySelectorAll('input[name="relatedDepartments"]:checked')).map(cb => cb.value);

    return {
      申請者ID: currentUserId,
      申請種別: container.querySelector('#document-type').value,
      申請タイトル: container.querySelector('#application-title').value.trim(),
      申請内容: container.querySelector('#application-content').value.trim(),
      申請金額: container.querySelector('#application-amount').value ? parseInt(container.querySelector('#application-amount').value) : null,
      申請開始日: container.querySelector('#application-date').value,
      申請終了日: null,
      承認状態: isDraft ? '下書き' : '申請中',
      現在承認者ID: null,
      承認段階: 0,
      最終承認者ID: null,
      最終承認日時: null,
      緊急フラグ: urgencyElement ? urgencyElement.value === 'urgent' : false,
      添付ファイル有無: selectedFiles.length > 0,
      備考: container.querySelector('#application-reason').value.trim(),
      作成者ID: currentUserId,
      更新者ID: currentUserId
    };
  }

  // 申請書類保存
  async function saveApplication(isDraft = false) {
    if (!isDraft && !validateForm()) {
      return;
    }

    try {
      const formData = collectFormData(isDraft);
      const saved = await window.aivicApi.save(1, formData); // 申請書類テーブル

      if (saved) {
        alert(isDraft ? '下書きを保存しました。' : '申請書類が正常に作成されました。');
        // フォームリセット
        container.querySelector('#application-form').reset();
        selectedFiles = [];
        updateFileList();
        setTodayDate();
        container.querySelector('input[name="urgency"][value="normal"]').checked = true;
      } else {
        alert('保存に失敗しました。');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存中にエラーが発生しました。');
    }
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 文字数カウンター
    container.querySelector('#application-content').addEventListener('input', () => {
      updateCounter('application-content', 'content-counter', 2000);
    });

    container.querySelector('#application-reason').addEventListener('input', () => {
      updateCounter('application-reason', 'reason-counter', 1000);
    });

    // ファイルアップロード
    const fileUploadArea = container.querySelector('#file-upload-area');
    const fileInput = container.querySelector('#file-input');

    fileUploadArea.addEventListener('click', () => {
      fileInput.click();
    });

    fileInput.addEventListener('change', (e) => {
      handleFileUpload(e.target.files);
    });

    // ドラッグ&ドロップ
    fileUploadArea.addEventListener('dragover', (e) => {
      e.preventDefault();
      fileUploadArea.style.borderColor = 'var(--primary)';
    });

    fileUploadArea.addEventListener('dragleave', (e) => {
      e.preventDefault();
      fileUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    });

    fileUploadArea.addEventListener('drop', (e) => {
      e.preventDefault();
      fileUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
      handleFileUpload(e.dataTransfer.files);
    });

    // ファイル削除
    container.addEventListener('click', (e) => {
      if (e.target.classList.contains('remove-file')) {
        const index = parseInt(e.target.dataset.index);
        selectedFiles.splice(index, 1);
        updateFileList();
      }
    });

    // ボタンイベント
    container.querySelector('#btn-upload').addEventListener('click', () => {
      window.showScreen("scr-1779422207222");
    });

    container.querySelector('#btn-draft').addEventListener('click', () => {
      saveApplication(true);
    });

    container.querySelector('#btn-submit').addEventListener('click', () => {
      saveApplication(false);
    });

    // ホバーエフェクト
    const submitBtn = container.querySelector('#btn-submit');
    submitBtn.addEventListener('mouseenter', () => {
      submitBtn.style.background = 'var(--primary-hover)';
    });
    submitBtn.addEventListener('mouseleave', () => {
      submitBtn.style.background = 'var(--primary)';
    });

    const secondaryBtns = container.querySelectorAll('button[style*="background: transparent"]');
    secondaryBtns.forEach(btn => {
      btn.addEventListener('mouseenter', () => {
        btn.style.background = 'rgba(255,255,255,0.05)';
      });
      btn.addEventListener('mouseleave', () => {
        btn.style.background = 'transparent';
      });
    });
  }

  // 初期化
  async function init() {
    await loadCurrentUser();
    setTodayDate();
    setupEventListeners();
    updateCounter('application-content', 'content-counter', 2000);
    updateCounter('application-reason', 'reason-counter', 1000);
  }

  init();
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let processLogs = [];

  // 処理ログ再描画関数
  function renderLogs(logs) {
    const tbody = container.querySelector("#log-tbody");
    tbody.innerHTML = logs.map(log => `
      <tr>
        <td>${log.executedAt || ""}</td>
        <td>${log.fileName || ""}</td>
        <td>${log.processType || ""}</td>
        <td>${log.classificationResult || ""}</td>
        <td>${log.accuracy || ""}</td>
        <td>${log.processingTime || ""}</td>
        <td>${log.message || ""}</td>
      </tr>
    `).join("");
  }

  // エラー表示関数
  function showError(message) {
    const errorEl = container.querySelector("#error-message");
    errorEl.textContent = message;
    errorEl.style.display = "block";
    setTimeout(() => {
      errorEl.style.display = "none";
    }, 5000);
  }

  // ファイルアップロード処理
  function handleFileUpload(file) {
    if (!file) return;

    // ファイル形式チェック
    const allowedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx'];
    const fileExt = '.' + file.name.split('.').pop().toLowerCase();
    if (!allowedTypes.includes(fileExt)) {
      showError("対応していないファイル形式です。PDF、Word、Excelファイルのみアップロード可能です。");
      return;
    }

    // ファイルサイズチェック（50MB制限）
    const maxSize = 50 * 1024 * 1024;
    if (file.size > maxSize) {
      showError("ファイルサイズが制限を超えています。50MB以下のファイルを選択してください。");
      return;
    }

    currentFile = file;

    // ファイル情報表示
    const fileInfo = container.querySelector("#file-info");
    const uploadText = container.querySelector("#upload-text");
    fileInfo.innerHTML = `
      <div style="font-weight: 500;">${file.name}</div>
      <div style="font-size: 11px; color: var(--text-muted);">${(file.size / 1024 / 1024).toFixed(2)} MB</div>
    `;
    fileInfo.style.display = "block";
    uploadText.style.display = "none";

    // プレビュー表示
    const preview = container.querySelector("#document-preview");
    if (file.type === 'application/pdf') {
      preview.innerHTML = `
        <div style="text-align: center;">
          <div style="font-size: 48px; margin-bottom: 8px;">📄</div>
          <div style="color: var(--text);">${file.name}</div>
          <div style="font-size: 11px; color: var(--text-muted);">PDFファイル</div>
        </div>
      `;
    } else {
      preview.innerHTML = `
        <div style="text-align: center;">
          <div style="font-size: 48px; margin-bottom: 8px;">📄</div>
          <div style="color: var(--text);">${file.name}</div>
          <div style="font-size: 11px; color: var(--text-muted);">文書ファイル</div>
        </div>
      `;
    }

    // 自動判別実行
    executeClassification();
  }

  // 文書種別判別実行
  function executeClassification() {
    if (!currentFile) {
      showError("ファイルが選択されていません。");
      return;
    }

    const startTime = Date.now();

    // 模擬的な判別処理
    setTimeout(() => {
      const mockResults = [
        { type: "申請書", confidence: 0.92, keywords: ["申請", "承認", "申請者", "申請日"], ocrText: "申請書\n申請者: 田中太郎\n申請日: 2024年1月15日\n件名: 経費申請について" },
        { type: "報告書", confidence: 0.87, keywords: ["報告", "結果", "実施", "完了"], ocrText: "月次報告書\n実施期間: 2024年1月\n担当者: 佐藤花子\n実施結果について報告いたします" },
        { type: "契約書", confidence: 0.95, keywords: ["契約", "甲", "乙", "条項"], ocrText: "業務委託契約書\n甲: 株式会社ABC\n乙: 株式会社XYZ\n第1条 契約の目的" },
        { type: "稟議書", confidence: 0.89, keywords: ["稟議", "決裁", "承認", "起案"], ocrText: "稟議書\n起案者: 山田次郎\n件名: 新システム導入について\n決裁をお願いいたします" }
      ];

      const result = mockResults[Math.floor(Math.random() * mockResults.length)];
      const processingTime = Date.now() - startTime;

      // 判別結果表示
      container.querySelector("#auto-classification").value = result.type;
      container.querySelector("#confidence-score").textContent = `${(result.confidence * 100).toFixed(1)}%`;

      // OCR結果表示
      container.querySelector("#ocr-results").textContent = result.ocrText;

      // キーワード表示
      const keywordsContainer = container.querySelector("#keywords-list");
      keywordsContainer.innerHTML = result.keywords.map(keyword => 
        `<span style="background: var(--primary); color: #fff; padding: 4px 8px; border-radius: 12px; font-size: 11px;">${keyword}</span>`
      ).join("");

      // 補助金関連度（模擬）
      const subsidyRelevance = Math.floor(Math.random() * 3) + 1;
      const relevanceLabels = { 1: "低", 2: "中", 3: "高" };
      const relevancePercentage = Math.floor(Math.random() * 40) + (subsidyRelevance * 20);

      container.querySelector("#subsidy-relevance").textContent = relevanceLabels[subsidyRelevance];
      container.querySelector("#relevance-percentage").textContent = `${relevancePercentage}%`;

      // 承認フロー設定
      const approvalSteps = Math.floor(Math.random() * 3) + 2;
      const approvers = ["部長", "課長", "係長"].slice(0, approvalSteps).join(" → ");
      const flowName = `${result.type}承認フロー`;

      container.querySelector("#approval-steps").textContent = `${approvalSteps}段階`;
      container.querySelector("#approvers").textContent = approvers;
      container.querySelector("#flow-name").textContent = flowName;

      // ログ追加
      const logEntry = {
        executedAt: new Date().toLocaleString(),
        fileName: currentFile.name,
        processType: "自動判別",
        classificationResult: result.type,
        accuracy: `${(result.confidence * 100).toFixed(1)}%`,
        processingTime: `${processingTime}ms`,
        message: "正常に完了しました"
      };
      processLogs.unshift(logEntry);
      renderLogs(processLogs);

    }, 1500);
  }

  // ファイル入力イベント
  const fileInput = container.querySelector("#file-input");
  fileInput.addEventListener("change", (e) => {
    if (e.target.files.length > 0) {
      handleFileUpload(e.target.files[0]);
    }
  });

  // ドラッグ&ドロップ
  const uploadArea = container.querySelector("#upload-area");
  uploadArea.addEventListener("click", () => fileInput.click());
  uploadArea.addEventListener("dragover", (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = "var(--primary)";
  });
  uploadArea.addEventListener("dragleave", () => {
    uploadArea.style.borderColor = "rgba(255,255,255,0.18)";
  });
  uploadArea.addEventListener("drop", (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = "rgba(255,255,255,0.18)";
    if (e.dataTransfer.files.length > 0) {
      handleFileUpload(e.dataTransfer.files[0]);
    }
  });

  // 判別実行ボタン
  container.querySelector("#btn-classify").addEventListener("click", () => {
    executeClassification();
  });

  // 再判別ボタン
  container.querySelector("#btn-reclassify").addEventListener("click", () => {
    if (!currentFile) {
      showError("ファイルが選択されていません。");
      return;
    }

    // 結果をクリア
    container.querySelector("#auto-classification").value = "";
    container.querySelector("#confidence-score").textContent = "-";
    container.querySelector("#ocr-results").textContent = "再判別処理中...";
    container.querySelector("#keywords-list").innerHTML = "";
    container.querySelector("#subsidy-relevance").textContent = "-";
    container.querySelector("#relevance-percentage").textContent = "-%";
    container.querySelector("#approval-steps").textContent = "-";
    container.querySelector("#approvers").textContent = "-";
    container.querySelector("#flow-name").textContent = "-";

    // 再判別実行
    executeClassification();
  });

  // 判別結果確定ボタン
  container.querySelector("#btn-confirm").addEventListener("click", () => {
    const autoResult = container.querySelector("#auto-classification").value;
    const manualResult = container.querySelector("#manual-classification").value;

    if (!autoResult && !manualResult) {
      showError("文書種別が判別されていません。");
      return;
    }

    const finalResult = manualResult || autoResult;

    // ログ追加
    const logEntry = {
      executedAt: new Date().toLocaleString(),
      fileName: currentFile ? currentFile.name : "-",
      processType: "結果確定",
      classificationResult: finalResult,
      accuracy: container.querySelector("#confidence-score").textContent,
      processingTime: "-",
      message: "判別結果を確定しました"
    };
    processLogs.unshift(logEntry);
    renderLogs(processLogs);

    // 次画面へ遷移
    window.showScreen('scr-1779422241190');
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    currentFile = null;
    container.querySelector("#file-input").value = "";
    container.querySelector("#upload-text").style.display = "block";
    container.querySelector("#file-info").style.display = "none";
    container.querySelector("#document-preview").innerHTML = "ファイルを選択してください";
    container.querySelector("#auto-classification").value = "";
    container.querySelector("#manual-classification").value = "";
    container.querySelector("#confidence-score").textContent = "-";
    container.querySelector("#ocr-results").textContent = "OCR解析を実行してください";
    container.querySelector("#keywords-list").innerHTML = "";
    container.querySelector("#subsidy-relevance").textContent = "-";
    container.querySelector("#relevance-percentage").textContent = "-%";
    container.querySelector("#approval-steps").textContent = "-";
    container.querySelector("#approvers").textContent = "-";
    container.querySelector("#flow-name").textContent = "-";
  });

  // 手動選択変更時
  container.querySelector("#manual-classification").addEventListener("change", (e) => {
    if (e.target.value && currentFile) {
      const logEntry = {
        executedAt: new Date().toLocaleString(),
        fileName: currentFile.name,
        processType: "手動選択",
        classificationResult: e.target.value,
        accuracy: "100%",
        processingTime: "-",
        message: "手動で文書種別を選択しました"
      };
      processLogs.unshift(logEntry);
      renderLogs(processLogs);
    }
  });

  // 初期ログ表示
  renderLogs(processLogs);
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#applications-tbody");
  const errorMessage = container.querySelector("#error-message");
  const thresholdSlider = container.querySelector("#threshold-slider");
  const thresholdValue = container.querySelector("#threshold-value");

  // 滞留日数計算
  function calculateStagnantDays(createdAt) {
    const created = new Date(createdAt);
    const now = new Date();
    const diffTime = Math.abs(now - created);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }

  // 緊急度の表示
  function getPriorityDisplay(priority) {
    const priorityMap = {
      1: { text: '低', color: '#10b981' },
      2: { text: '中', color: '#f59e0b' },
      3: { text: '高', color: '#ef4444' },
      4: { text: '緊急', color: '#dc2626' }
    };
    const p = priorityMap[priority] || { text: '通常', color: '#6b7280' };
    return `<span style="color: ${p.color}; font-weight: 500;">${p.text}</span>`;
  }

  // 承認状態の表示
  function getStatusDisplay(status) {
    const statusMap = {
      '申請中': { text: '申請中', color: '#3b82f6' },
      '承認待ち': { text: '承認待ち', color: '#f59e0b' },
      '承認済': { text: '承認済', color: '#10b981' },
      '却下': { text: '却下', color: '#ef4444' },
      '差戻し': { text: '差戻し', color: '#f97316' }
    };
    const s = statusMap[status] || { text: status, color: '#6b7280' };
    return `<span style="color: ${s.color}; font-weight: 500;">${s.text}</span>`;
  }

  // テーブル再描画
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">該当する滞留案件はありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const stagnantDays = calculateStagnantDays(row.作成日時 || row.createdAt || new Date());
      const applicantName = row.申請者名 || row.申請者 || '';
      const currentApprover = row.現在承認者名 || row.現在承認者 || '';
      const documentType = row.申請種別 || row.文書種別名 || '';
      const documentNumber = row.申請書類番号 || row.申請書類ID || '';
      const approvalStage = row.承認段階 || row.現在ステップ番号 || 1;
      const priority = row.優先度 || row.緊急度 || 2;
      const status = row.承認状態 || row.処理状況 || '申請中';

      return `
        <tr data-id="${row.id || row.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${documentNumber}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${documentType}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${applicantName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${currentApprover}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getStatusDisplay(status)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); font-weight: 500;">
            <span style="color: ${stagnantDays > 7 ? '#ef4444' : stagnantDays > 3 ? '#f59e0b' : '#10b981'};">${stagnantDays}日</span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">${getPriorityDisplay(priority)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${row.id || row.申請書類ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">詳細</button>
            <button class="action-btn secondary notify-btn" data-id="${row.id || row.申請書類ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">催促</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 検索フィルタ
  function filterRows(allRows) {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const documentType = container.querySelector("#document-type").value;
    const applicantName = container.querySelector("#applicant-name").value.toLowerCase();
    const assignee = container.querySelector("#assignee").value;
    const documentNumber = container.querySelector("#document-number").value.toLowerCase();
    const threshold = parseInt(thresholdSlider.value);
    const selectedSteps = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);
    const selectedPriority = container.querySelector('input[name="priority"]:checked')?.value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError('終了日は開始日以降の日付を入力してください');
      return [];
    }

    return allRows.filter(row => {
      const createdDate = new Date(row.作成日時 || row.createdAt || new Date());
      const stagnantDays = calculateStagnantDays(row.作成日時 || row.createdAt || new Date());

      // 日付範囲フィルタ
      if (startDate && createdDate < new Date(startDate)) return false;
      if (endDate && createdDate > new Date(endDate)) return false;

      // 文書種別フィルタ
      if (documentType && (row.申請種別 || row.文書種別名 || '') !== documentType) return false;

      // 申請者名フィルタ（部分一致）
      if (applicantName && !(row.申請者名 || row.申請者 || '').toLowerCase().includes(applicantName)) return false;

      // 担当者フィルタ
      if (assignee && (row.現在承認者名 || row.現在承認者 || '') !== assignee) return false;

      // 申請書類番号フィルタ（部分一致）
      if (documentNumber && !(row.申請書類番号 || row.申請書類ID || '').toLowerCase().includes(documentNumber)) return false;

      // 滞留日数閾値フィルタ
      if (stagnantDays < threshold) return false;

      // 承認ステップフィルタ
      if (selectedSteps.length > 0) {
        const currentStatus = row.承認状態 || row.処理状況 || '';
        if (!selectedSteps.some(step => currentStatus.includes(step.replace('承認', '')))) return false;
      }

      // 緊急度フィルタ
      if (selectedPriority) {
        const priorityMap = { '低': 1, '中': 2, '高': 3 };
        const rowPriority = row.優先度 || row.緊急度 || 2;
        if (rowPriority !== priorityMap[selectedPriority]) return false;
      }

      return true;
    });
  }

  // CSVエクスポート
  function exportCSV(rows) {
    const headers = ['申請書類番号', '申請種別', '申請者', '現在承認者', '承認段階', '滞留日数', '緊急度', '作成日時'];
    const csvContent = [
      headers.join(','),
      ...rows.map(row => {
        const stagnantDays = calculateStagnantDays(row.作成日時 || row.createdAt || new Date());
        const priorityMap = { 1: '低', 2: '中', 3: '高', 4: '緊急' };
        const priority = priorityMap[row.優先度 || row.緊急度 || 2] || '中';

        return [
          `"${row.申請書類番号 || row.申請書類ID || ''}"`,
          `"${row.申請種別 || row.文書種別名 || ''}"`,
          `"${row.申請者名 || row.申請者 || ''}"`,
          `"${row.現在承認者名 || row.現在承認者 || ''}"`,
          `"${row.承認状態 || row.処理状況 || '申請中'}"`,
          stagnantDays,
          `"${priority}"`,
          `"${row.作成日時 || row.createdAt || ''}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `滞留案件一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      renderRows(rows);
    } else {
      renderRows(tables[1]?.records || []);
    }
  }).catch(() => {
    renderRows(tables[1]?.records || []);
  });

  // スライダー値更新
  thresholdSlider.addEventListener('input', () => {
    thresholdValue.textContent = thresholdSlider.value;
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    try {
      const allRows = await window.aivicApi.list(1) || tables[1]?.records || [];
      const filteredRows = filterRows(allRows);
      renderRows(filteredRows);
    } catch (error) {
      showError('検索処理中にエラーが発生しました');
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = '';
    container.querySelector("#end-date").value = '';
    container.querySelector("#document-type").value = '';
    container.querySelector("#applicant-name").value = '';
    container.querySelector("#assignee").value = '';
    container.querySelector("#document-number").value = '';
    thresholdSlider.value = '7';
    thresholdValue.textContent = '7';
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelectorAll('input[type="radio"]').forEach(rb => rb.checked = false);
    errorMessage.style.display = 'none';

    // 全件再表示
    window.aivicApi.list(1).then(rows => {
      renderRows(rows || tables[1]?.records || []);
    }).catch(() => {
      renderRows(tables[1]?.records || []);
    });
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const allRows = await window.aivicApi.list(1) || tables[1]?.records || [];
      const filteredRows = filterRows(allRows);
      exportCSV(filteredRows);
    } catch (error) {
      showError('CSVエクスポート中にエラーが発生しました');
    }
  });

  // 行レベル操作
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const notifyBtn = e.target.closest(".notify-btn");

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1779422434952"); // 申請書類確認画面
    }

    if (notifyBtn) {
      const id = notifyBtn.dataset.id;
      window.showScreen("scr-1779422392638"); // 催促通知送信処理
    }
  });
}

function(container, apiUrl, tables) {
  let currentSort = { field: null, direction: 'asc' };
  let allDelayedApplications = [];
  let selectedApplications = [];

  // 緊急度レベルのマッピング
  const urgencyLevels = {
    1: { text: '低', color: '#6b7280' },
    2: { text: '中', color: '#f59e0b' },
    3: { text: '高', color: '#ef4444' },
    4: { text: '緊急', color: '#dc2626' }
  };

  // 遅延申請データを取得・計算する関数
  function getDelayedApplications() {
    const applications = tables[0]?.records || [];
    const users = tables[1]?.records || [];
    const documentTypes = tables[2]?.records || [];
    const approvalSteps = tables[4]?.records || [];

    const now = new Date();

    return applications
      .filter(app => app.承認状態 === '申請中' || app.承認状態 === '承認待ち')
      .map(app => {
        const applicant = users.find(u => u.ユーザーID === app.申請者ID);
        const docType = documentTypes.find(d => d.文書種別ID === app.申請種別);
        const currentStep = approvalSteps.find(s => s.申請書類ID === app.申請書類ID && s.承認状態 === '未承認');
        const approver = currentStep ? users.find(u => u.ユーザーID === currentStep.承認者ID) : null;

        const createdDate = new Date(app.作成日時);
        const delayDays = Math.floor((now - createdDate) / (1000 * 60 * 60 * 24));

        // 緊急度レベルを遅延日数に基づいて決定
        let urgencyLevel = 1;
        if (delayDays >= 14) urgencyLevel = 4; // 緊急
        else if (delayDays >= 10) urgencyLevel = 3; // 高
        else if (delayDays >= 7) urgencyLevel = 2; // 中
        else urgencyLevel = 1; // 低

        return {
          ...app,
          申請者名: applicant?.ユーザー名 || '不明',
          文書種別名: docType?.文書種別名 || '不明',
          承認者名: approver?.ユーザー名 || '不明',
          承認者メール: approver?.メールアドレス || '',
          遅延日数: delayDays,
          緊急度レベル: urgencyLevel,
          承認ステップ番号: currentStep?.ステップ番号 || 1
        };
      })
      .filter(app => app.遅延日数 > 0); // 遅延している申請のみ
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#delayed-applications-tbody');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.style.display = 'block';
      return;
    }

    noDataMessage.style.display = 'none';
    tbody.innerHTML = rows.map(row => {
      const urgency = urgencyLevels[row.緊急度レベル] || urgencyLevels[1];
      const createdDate = new Date(row.作成日時).toLocaleDateString('ja-JP');
      const hasEmail = row.承認者メール && row.承認者メール.trim() !== '';

      return `
        <tr data-id="${row.申請書類ID}" style="height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            <input type="checkbox" class="row-checkbox" data-id="${row.申請書類ID}" style="accent-color: var(--primary);" ${!hasEmail ? 'disabled' : ''}>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請書類ID.substring(0, 8)}...</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請者名}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.文書種別名}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${createdDate}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">ステップ${row.承認ステップ番号}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.承認者名}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); font-weight: 500;">${row.遅延日数}日</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="background: ${urgency.color}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${urgency.text}</span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="notify-btn action-btn secondary" data-id="${row.申請書類ID}" ${!hasEmail ? 'disabled title="承認者のメールアドレスが未設定です"' : ''} style="font-size: 12px; padding: 4px 8px;">催促送信</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // フィルタリング関数
  function filterApplications() {
    const searchTerm = container.querySelector('#input-search').value.toLowerCase();
    const urgencyFilter = container.querySelector('#urgency-filter').value;
    const delayDaysFilter = parseInt(container.querySelector('#delay-days-filter').value) || 0;

    let filtered = allDelayedApplications.filter(app => {
      const matchesSearch = !searchTerm || 
        app.申請者名.toLowerCase().includes(searchTerm) ||
        app.申請書類ID.toLowerCase().includes(searchTerm) ||
        app.申請タイトル.toLowerCase().includes(searchTerm);

      const matchesUrgency = !urgencyFilter || app.緊急度レベル.toString() === urgencyFilter;
      const matchesDelayDays = app.遅延日数 >= delayDaysFilter;

      return matchesSearch && matchesUrgency && matchesDelayDays;
    });

    // ソート適用
    if (currentSort.field) {
      filtered.sort((a, b) => {
        let aVal = a[currentSort.field];
        let bVal = b[currentSort.field];

        if (currentSort.field === '遅延日数') {
          aVal = parseInt(aVal) || 0;
          bVal = parseInt(bVal) || 0;
        }

        if (currentSort.direction === 'asc') {
          return aVal > bVal ? 1 : -1;
        } else {
          return aVal < bVal ? 1 : -1;
        }
      });
    }

    renderRows(filtered);
    updateSelectAllState();
  }

  // 全選択チェックボックスの状態更新
  function updateSelectAllState() {
    const selectAll = container.querySelector('#select-all');
    const checkboxes = container.querySelectorAll('.row-checkbox:not([disabled])');
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');

    if (checkboxes.length === 0) {
      selectAll.indeterminate = false;
      selectAll.checked = false;
    } else if (checkedBoxes.length === checkboxes.length) {
      selectAll.indeterminate = false;
      selectAll.checked = true;
    } else if (checkedBoxes.length > 0) {
      selectAll.indeterminate = true;
      selectAll.checked = false;
    } else {
      selectAll.indeterminate = false;
      selectAll.checked = false;
    }
  }

  // 催促通知送信処理
  async function sendNotification(applicationIds, isBulk = false) {
    const modal = container.querySelector('#notify-modal');
    const content = container.querySelector('#notify-content');

    const applications = allDelayedApplications.filter(app => applicationIds.includes(app.申請書類ID));
    const validApplications = applications.filter(app => app.承認者メール && app.承認者メール.trim() !== '');

    if (validApplications.length === 0) {
      showError('承認者のメールアドレスが設定されていないため、催促通知を送信できません');
      return;
    }

    if (isBulk) {
      content.innerHTML = `
        <p>以下の${validApplications.length}件の申請について催促通知を送信します：</p>
        <ul style="margin: 8px 0; padding-left: 20px; max-height: 200px; overflow-y: auto;">
          ${validApplications.map(app => `<li>${app.申請者名} - ${app.申請タイトル || '申請書類'}</li>`).join('')}
        </ul>
      `;
    } else {
      const app = validApplications[0];
      content.innerHTML = `
        <p>以下の申請について催促通知を送信します：</p>
        <div style="background: var(--bg-main); padding: 12px; border-radius: 6px; margin: 8px 0;">
          <div><strong>申請者：</strong> ${app.申請者名}</div>
          <div><strong>申請内容：</strong> ${app.申請タイトル || '申請書類'}</div>
          <div><strong>承認者：</strong> ${app.承認者名}</div>
          <div><strong>遅延日数：</strong> ${app.遅延日数}日</div>
        </div>
      `;
    }

    modal.style.display = 'flex';

    return new Promise((resolve) => {
      const confirmBtn = container.querySelector('#btn-confirm-notify');
      const cancelBtn = container.querySelector('#btn-cancel-notify');

      const handleConfirm = async () => {
        modal.style.display = 'none';

        try {
          // 通知履歴に記録
          for (const app of validApplications) {
            const notificationData = {
              申請書類ID: app.申請書類ID,
              通知対象ユーザーID: app.現在承認者ID,
              通知種別: '催促通知',
              通知タイトル: `【催促】申請の承認をお願いします - ${app.申請タイトル || '申請書類'}`,
              通知内容: `申請者：${app.申請者名}\n申請日：${new Date(app.作成日時).toLocaleDateString('ja-JP')}\n遅延日数：${app.遅延日数}日\n\n承認処理をお願いいたします。`,
              送信方法: 'メール',
              送信先アドレス: app.承認者メール,
              送信状態: '送信完了',
              送信日時: new Date().toISOString(),
              既読フラグ: false,
              再送回数: 0,
              作成者ID: 'current-user-id'
            };

            await window.aivicApi.save(5, notificationData); // 通知履歴テーブル
          }

          showSuccess(`催促通知を${validApplications.length}件送信しました`);

          // チェックボックスをクリア
          container.querySelectorAll('.row-checkbox:checked').forEach(cb => cb.checked = false);
          updateSelectAllState();

        } catch (error) {
          showError('催促通知の送信に失敗しました: ' + error.message);
        }

        cleanup();
        resolve();
      };

      const handleCancel = () => {
        modal.style.display = 'none';
        cleanup();
        resolve();
      };

      const cleanup = () => {
        confirmBtn.removeEventListener('click', handleConfirm);
        cancelBtn.removeEventListener('click', handleCancel);
      };

      confirmBtn.addEventListener('click', handleConfirm);
      cancelBtn.addEventListener('click', handleCancel);
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => errorDiv.style.display = 'none', 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.style.display = 'block';
    setTimeout(() => successDiv.style.display = 'none', 3000);
  }

  // CSVエクスポート
  function exportToCSV() {
    const headers = ['申請書類番号', '申請者名', '文書種別', '申請日', '承認ステップ', '承認者名', '遅延日数', '緊急度レベル'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...allDelayedApplications.map(row => [
        `"${row.申請書類ID}"`,
        `"${row.申請者名}"`,
        `"${row.文書種別名}"`,
        `"${new Date(row.作成日時).toLocaleDateString('ja-JP')}"`,
        `"ステップ${row.承認ステップ番号}"`,
        `"${row.承認者名}"`,
        row.遅延日数,
        urgencyLevels[row.緊急度レベル]?.text || '不明'
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `遅延申請一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      // 最新データを取得
      const [applications, users, documentTypes, , approvalSteps] = await Promise.all([
        window.aivicApi.list(0), // 申請書類
        window.aivicApi.list(1), // ユーザー
        window.aivicApi.list(2), // 文書種別マスタ
        Promise.resolve([]), // 承認フロー定義（使用しない）
        window.aivicApi.list(4)  // 承認ステップ
      ]);

      // tablesを更新
      tables[0] = { ...tables[0], records: applications || [] };
      tables[1] = { ...tables[1], records: users || [] };
      tables[2] = { ...tables[2], records: documentTypes || [] };
      tables[4] = { ...tables[4], records: approvalSteps || [] };

      allDelayedApplications = getDelayedApplications();
      filterApplications();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      allDelayedApplications = getDelayedApplications();
      filterApplications();
    }
  }

  // イベントリスナー設定

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', filterApplications);

  // リアルタイム検索
  container.querySelector('#input-search').addEventListener('input', filterApplications);
  container.querySelector('#urgency-filter').addEventListener('change', filterApplications);
  container.querySelector('#delay-days-filter').addEventListener('input', filterApplications);

  // ソート機能
  container.querySelector('#sort-delay-days').addEventListener('click', () => {
    const icon = container.querySelector('#sort-icon');
    if (currentSort.field === '遅延日数' && currentSort.direction === 'asc') {
      currentSort.direction = 'desc';
      icon.textContent = '↓';
    } else {
      currentSort.field = '遅延日数';
      currentSort.direction = 'asc';
      icon.textContent = '↑';
    }
    filterApplications();
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox:not([disabled])');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括催促送信
  container.querySelector('#btn-bulk-notify').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');
    if (checkedBoxes.length === 0) {
      showError('催促通知を送信する申請を選択してください');
      return;
    }

    const applicationIds = Array.from(checkedBoxes).map(cb => cb.dataset.id);
    await sendNotification(applicationIds, true);
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

  // 行レベル操作（個別催促送信）
  container.addEventListener('click', async (e) => {
    const notifyBtn = e.target.closest('.notify-btn');
    if (notifyBtn && !notifyBtn.disabled) {
      const applicationId = notifyBtn.dataset.id;
      await sendNotification([applicationId], false);
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allNotifications = [];
  let filteredNotifications = [];

  // 緊急度アイコンを取得する関数
  function getPriorityIcon(priority) {
    switch(parseInt(priority)) {
      case 4: return '<span style="color: #ff4444; font-size: 14px;">🚨</span>';
      case 3: return '<span style="color: #ff6a00; font-size: 14px;">⚡</span>';
      case 2: return '<span style="color: #ffa500; font-size: 14px;">⚠️</span>';
      case 1: return '<span style="color: #4a90e2; font-size: 14px;">ℹ️</span>';
      default: return '<span style="color: var(--text-muted); font-size: 14px;">-</span>';
    }
  }

  // 緊急度テキストを取得する関数
  function getPriorityText(priority) {
    switch(parseInt(priority)) {
      case 4: return '緊急';
      case 3: return '高';
      case 2: return '中';
      case 1: return '低';
      default: return '-';
    }
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP', {
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 期限チェック関数
  function isOverdue(deadline) {
    if (!deadline) return false;
    return new Date(deadline) < new Date();
  }

  // 期限が近いかチェック関数
  function isNearDeadline(deadline) {
    if (!deadline) return false;
    const now = new Date();
    const deadlineDate = new Date(deadline);
    const diffHours = (deadlineDate - now) / (1000 * 60 * 60);
    return diffHours > 0 && diffHours <= 24;
  }

  // 通知データを構築する関数
  function buildNotificationData() {
    const notifications = [];
    const notificationHistory = tables.find(t => t.tableName === '通知履歴')?.records || [];
    const applications = tables.find(t => t.tableName === '申請書類')?.records || [];
    const users = tables.find(t => t.tableName === 'ユーザー')?.records || [];
    const approvalSteps = tables.find(t => t.tableName === '承認ステップ')?.records || [];

    notificationHistory.forEach(notification => {
      const application = applications.find(app => app.申請書類ID === notification.申請書類ID);
      const applicant = users.find(user => user.ユーザーID === (application?.申請者ID));
      const step = approvalSteps.find(step => step.承認ステップID === notification.承認ステップID);

      if (application && applicant) {
        notifications.push({
          id: notification.通知履歴ID,
          notificationDate: notification.送信日時 || notification.作成日時,
          applicationId: application.申請書類ID,
          applicationTitle: application.申請タイトル,
          applicantName: applicant.ユーザー名,
          documentType: application.申請種別,
          priority: application.緊急フラグ ? 4 : 2,
          deadline: step?.期限日時,
          isRead: notification.既読フラグ,
          notificationType: notification.通知種別
        });
      }
    });

    return notifications.sort((a, b) => new Date(b.notificationDate) - new Date(a.notificationDate));
  }

  // テーブル再描画関数
  function renderRows(notifications) {
    const tbody = container.querySelector('#notification-tbody');
    const emptyMessage = container.querySelector('#empty-message');

    if (!notifications || notifications.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.style.display = 'block';
      updatePagination(0);
      return;
    }

    emptyMessage.style.display = 'none';

    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageNotifications = notifications.slice(startIndex, endIndex);

    tbody.innerHTML = pageNotifications.map(notification => {
      const isOverdueFlag = isOverdue(notification.deadline);
      const isNearDeadlineFlag = isNearDeadline(notification.deadline);
      const rowStyle = !notification.isRead ? 'background: rgba(74, 144, 226, 0.05); font-weight: 500;' : '';

      return `
        <tr data-id="${notification.id}" style="${rowStyle}">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${formatDateTime(notification.notificationDate)}
            ${!notification.isRead ? '<span style="color: var(--primary); font-size: 10px; margin-left: 4px;">●</span>' : ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <a href="#" class="document-link" data-application-id="${notification.applicationId}" 
               style="color: var(--primary); text-decoration: none; cursor: pointer;">
              ${notification.applicationTitle || '無題'}
            </a>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${notification.applicantName || '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <div style="display: flex; align-items: center; gap: 4px;">
              ${getPriorityIcon(notification.priority)}
              <span style="color: var(--text);">${getPriorityText(notification.priority)}</span>
            </div>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="color: ${isOverdueFlag ? '#ff4444' : isNearDeadlineFlag ? '#ff6a00' : 'var(--text)'};">
              ${formatDateTime(notification.deadline)}
              ${isOverdueFlag ? ' <span style="font-size: 10px;">期限超過</span>' : ''}
              ${isNearDeadlineFlag ? ' <span style="font-size: 10px;">期限間近</span>' : ''}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary mark-read-btn" data-id="${notification.id}" 
                    style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;"
                    ${notification.isRead ? 'disabled' : ''}>
              ${notification.isRead ? '既読' : '既読にする'}
            </button>
          </td>
        </tr>
      `;
    }).join('');

    updatePagination(notifications.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector('#page-info');
    const btnPrev = container.querySelector('#btn-prev');
    const btnNext = container.querySelector('#btn-next');

    pageInfo.textContent = `${currentPage} / ${Math.max(1, totalPages)}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;

    btnPrev.style.opacity = btnPrev.disabled ? '0.5' : '1';
    btnNext.style.opacity = btnNext.disabled ? '0.5' : '1';
  }

  // 未読件数バッジ更新
  function updateUnreadBadge() {
    const unreadCount = allNotifications.filter(n => !n.isRead).length;
    const badge = container.querySelector('#unread-badge');

    if (unreadCount > 0) {
      badge.textContent = unreadCount;
      badge.style.display = 'inline-block';
    } else {
      badge.style.display = 'none';
    }
  }

  // 遅延警告アラート更新
  function updateDelayAlert() {
    const overdueNotifications = allNotifications.filter(n => isOverdue(n.deadline));
    const nearDeadlineNotifications = allNotifications.filter(n => isNearDeadline(n.deadline));
    const alertDiv = container.querySelector('#delay-alert');
    const messageDiv = container.querySelector('#delay-message');

    if (overdueNotifications.length > 0 || nearDeadlineNotifications.length > 0) {
      let message = '';
      if (overdueNotifications.length > 0) {
        message += `期限超過: ${overdueNotifications.length}件`;
      }
      if (nearDeadlineNotifications.length > 0) {
        if (message) message += ' / ';
        message += `期限間近: ${nearDeadlineNotifications.length}件`;
      }
      messageDiv.textContent = message;
      alertDiv.style.display = 'block';
    } else {
      alertDiv.style.display = 'none';
    }
  }

  // 申請者フィルター選択肢を構築
  function populateApplicantFilter() {
    const applicantFilter = container.querySelector('#filter-applicant');
    const users = tables.find(t => t.tableName === 'ユーザー')?.records || [];

    // 既存の選択肢をクリア（最初の「すべて」以外）
    while (applicantFilter.children.length > 1) {
      applicantFilter.removeChild(applicantFilter.lastChild);
    }

    // 申請者として使われているユーザーのみを追加
    const applicantIds = [...new Set(allNotifications.map(n => {
      const applications = tables.find(t => t.tableName === '申請書類')?.records || [];
      const app = applications.find(a => a.申請書類ID === n.applicationId);
      return app?.申請者ID;
    }).filter(Boolean))];

    applicantIds.forEach(userId => {
      const user = users.find(u => u.ユーザーID === userId);
      if (user) {
        const option = document.createElement('option');
        option.value = user.ユーザー名;
        option.textContent = user.ユーザー名;
        applicantFilter.appendChild(option);
      }
    });
  }

  // フィルター適用
  function applyFilters() {
    const priorityFilter = container.querySelector('#filter-priority').value;
    const documentTypeFilter = container.querySelector('#filter-document-type').value;
    const applicantFilter = container.querySelector('#filter-applicant').value;
    const deadlineFilter = container.querySelector('#filter-deadline').value;

    filteredNotifications = allNotifications.filter(notification => {
      // 緊急度フィルター
      if (priorityFilter && notification.priority.toString() !== priorityFilter) {
        return false;
      }

      // 文書種別フィルター
      if (documentTypeFilter && notification.documentType !== documentTypeFilter) {
        return false;
      }

      // 申請者フィルター
      if (applicantFilter && notification.applicantName !== applicantFilter) {
        return false;
      }

      // 期限フィルター
      if (deadlineFilter) {
        const now = new Date();
        const deadline = new Date(notification.deadline);

        switch (deadlineFilter) {
          case 'today':
            if (deadline.toDateString() !== now.toDateString()) return false;
            break;
          case 'week':
            const weekFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
            if (deadline > weekFromNow) return false;
            break;
          case 'month':
            const monthFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
            if (deadline > monthFromNow) return false;
            break;
          case 'overdue':
            if (deadline >= now) return false;
            break;
        }
      }

      return true;
    });

    currentPage = 1;
    renderRows(filteredNotifications);
  }

  // データ読み込みとレンダリング
  async function loadData() {
    try {
      // 最新データを取得
      const notificationHistoryTable = tables.findIndex(t => t.tableName === '通知履歴');
      if (notificationHistoryTable >= 0) {
        const latestData = await window.aivicApi.list(notificationHistoryTable);
        if (latestData) {
          tables[notificationHistoryTable].records = latestData;
        }
      }

      allNotifications = buildNotificationData();
      filteredNotifications = [...allNotifications];

      populateApplicantFilter();
      renderRows(filteredNotifications);
      updateUnreadBadge();
      updateDelayAlert();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      // 初期データで表示
      allNotifications = buildNotificationData();
      filteredNotifications = [...allNotifications];
      populateApplicantFilter();
      renderRows(filteredNotifications);
      updateUnreadBadge();
      updateDelayAlert();
    }
  }

  // 初期データ読み込み
  loadData();

  // 検索ボタンイベント
  container.querySelector('#btn-search').addEventListener('click', () => {
    applyFilters();
  });

  // フィルタークリアボタンイベント
  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#filter-priority').value = '';
    container.querySelector('#filter-document-type').value = '';
    container.querySelector('#filter-applicant').value = '';
    container.querySelector('#filter-deadline').value = '';

    filteredNotifications = [...allNotifications];
    currentPage = 1;
    renderRows(filteredNotifications);
  });

  // 更新ボタンイベント
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    loadData();
  });

  // ページネーションイベント
  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredNotifications);
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredNotifications.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredNotifications);
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 申請書類リンククリック
    const documentLink = e.target.closest('.document-link');
    if (documentLink) {
      e.preventDefault();
      const applicationId = documentLink.dataset.applicationId;
      if (applicationId) {
        window.showScreen("scr-1779422434952");
      }
      return;
    }

    // 既読ボタンクリック
    const markReadBtn = e.target.closest('.mark-read-btn');
    if (markReadBtn && !markReadBtn.disabled) {
      const notificationId = markReadBtn.dataset.id;
      try {
        const notificationHistoryTable = tables.findIndex(t => t.tableName === '通知履歴');
        if (notificationHistoryTable >= 0) {
          await window.aivicApi.update(notificationHistoryTable, notificationId, {
            既読フラグ: true,
            既読日時: new Date().toISOString()
          });

          // ローカルデータも更新
          const notification = allNotifications.find(n => n.id === notificationId);
          if (notification) {
            notification.isRead = true;
          }

          renderRows(filteredNotifications);
          updateUnreadBadge();
        }
      } catch (error) {
        console.error('既読更新エラー:', error);
        alert('既読の更新に失敗しました');
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const APPLICATION_TABLE = 1; // 申請書類
  const APPROVAL_HISTORY_TABLE = 5; // 承認履歴
  const APPROVAL_STEP_TABLE = 4; // 承認ステップ

  let currentApplicationId = null;

  // 承認履歴の再描画関数
  function renderApprovalHistory(histories) {
    const tbody = container.querySelector('#approval-history-tbody');
    if (!histories || histories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; color: var(--text-muted); padding: 20px;">承認履歴はありません</td></tr>';
      return;
    }

    tbody.innerHTML = histories.map(h => `
      <tr>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${h.承認者名 || '未設定'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${getStatusStyle(h.承認結果)}">${h.承認結果 || '未処理'}</span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDateTime(h.承認日時)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${h.承認コメント || ''}</td>
      </tr>
    `).join('');
  }

  // ステータススタイル取得
  function getStatusStyle(status) {
    switch(status) {
      case '承認': return 'background: rgba(34, 197, 94, 0.2); color: #22c55e;';
      case '却下': return 'background: rgba(239, 68, 68, 0.2); color: #ef4444;';
      case '差戻し': return 'background: rgba(245, 158, 11, 0.2); color: #f59e0b;';
      default: return 'background: rgba(156, 163, 175, 0.2); color: #9ca3af;';
    }
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return `${date.getFullYear()}/${String(date.getMonth() + 1).padStart(2, '0')}/${String(date.getDate()).padStart(2, '0')} ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
  }

  // 申請書類データの読み込み
  async function loadApplicationData() {
    try {
      const applications = await window.aivicApi.list(APPLICATION_TABLE);
      if (applications && applications.length > 0) {
        // 承認待ちの申請を取得（実際の実装では画面パラメータから取得）
        const app = applications.find(a => a.承認状態 === '申請中') || applications[0];
        currentApplicationId = app.申請書類ID;

        // 申請情報を画面に反映
        container.querySelector('#applicant-name').textContent = app.申請者名 || '田中 太郎';
        container.querySelector('#document-type').textContent = app.申請種別 || '経費申請';
        container.querySelector('#application-date').textContent = formatDateTime(app.作成日時);
        container.querySelector('#application-title').textContent = app.申請タイトル || 'タイトル未設定';
        container.querySelector('#application-amount').textContent = app.申請金額 ? `¥${app.申請金額.toLocaleString()}` : '-';
        container.querySelector('#application-content').innerHTML = app.申請内容 || '申請内容が入力されていません。';

        // 承認履歴を読み込み
        loadApprovalHistory(currentApplicationId);
      }
    } catch (error) {
      console.error('申請データの読み込みに失敗:', error);
    }
  }

  // 承認履歴の読み込み
  async function loadApprovalHistory(applicationId) {
    try {
      const histories = await window.aivicApi.list(APPROVAL_HISTORY_TABLE);
      const filtered = histories ? histories.filter(h => h.申請書類ID === applicationId) : [];
      renderApprovalHistory(filtered);
    } catch (error) {
      console.error('承認履歴の読み込みに失敗:', error);
      renderApprovalHistory([]);
    }
  }

  // コメント文字数カウント
  const commentTextarea = container.querySelector('#approval-comment');
  const commentCount = container.querySelector('#comment-count');

  commentTextarea.addEventListener('input', function() {
    const count = this.value.length;
    commentCount.textContent = count;

    if (count > 500) {
      this.value = this.value.substring(0, 500);
      commentCount.textContent = '500';
    }
  });

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    errorDiv.style.display = 'block';
  }

  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
    errorDiv.style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    const decision = container.querySelector('input[name="decision"]:checked');
    const comment = container.querySelector('#approval-comment').value.trim();

    if (!decision) {
      showError('承認判断を選択してください。');
      return false;
    }

    if ((decision.value === 'reject' || decision.value === 'return') && !comment) {
      showError('却下または差戻しの場合、コメントの入力が必須です。');
      return false;
    }

    if (comment.length < 1 && decision.value !== 'approve') {
      showError('コメントは1文字以上入力してください。');
      return false;
    }

    hideError();
    return true;
  }

  // 判断確定ボタン
  container.querySelector('[data-testid="submit-decision-button"]').addEventListener('click', async function() {
    if (!validateForm()) return;

    const decision = container.querySelector('input[name="decision"]:checked').value;
    const comment = container.querySelector('#approval-comment').value.trim();
    const conditionalApproval = container.querySelector('#conditional-approval').checked;

    try {
      // 承認履歴に記録
      const historyData = {
        申請書類ID: currentApplicationId,
        承認者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを取得
        承認結果: decision === 'approve' ? (conditionalApproval ? '条件付き承認' : '承認') : 
                 decision === 'reject' ? '却下' : '差戻し',
        承認コメント: comment,
        承認日時: new Date().toISOString(),
        承認順序: 1,
        代理承認フラグ: false
      };

      const saved = await window.aivicApi.save(APPROVAL_HISTORY_TABLE, historyData);
      if (saved) {
        // 申請書類のステータス更新
        const newStatus = decision === 'approve' ? '承認済' : 
                         decision === 'reject' ? '却下' : '差戻し';

        await window.aivicApi.update(APPLICATION_TABLE, currentApplicationId, {
          承認状態: newStatus,
          最終承認日時: new Date().toISOString()
        });

        // 結果通知処理画面へ遷移
        window.showScreen("scr-1779422470870");
      }
    } catch (error) {
      showError('承認判断の保存に失敗しました。');
      console.error('承認判断保存エラー:', error);
    }
  });

  // 戻るボタン
  container.querySelector('[data-testid="back-button"]').addEventListener('click', function() {
    window.showScreen("scr-1779422434952");
  });

  // ファイルプレビュー機能
  container.addEventListener('click', function(e) {
    if (e.target.matches('[data-testid="preview-button"]')) {
      const modal = container.querySelector('#file-preview-modal');
      const previewContent = container.querySelector('#preview-content');

      previewContent.innerHTML = '<p style="color: #666;">PDFファイルのプレビューを表示中...</p>';
      modal.style.display = 'block';
      modal.classList.remove('hidden');
    }
  });

  // プレビューモーダル閉じる
  container.querySelector('#close-preview').addEventListener('click', function() {
    const modal = container.querySelector('#file-preview-modal');
    modal.style.display = 'none';
    modal.classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#file-preview-modal').addEventListener('click', function(e) {
    if (e.target === this) {
      this.style.display = 'none';
      this.classList.add('hidden');
    }
  });

  // 初期データ読み込み
  loadApplicationData();
}

function(container, apiUrl, tables) {
  let editingId = null;
  let deleteTargetId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#classification-tbody");
    tbody.innerHTML = rows.map(r => {
      const subsidyLevelText = r.補助金関連度レベル === 1 ? '低' : r.補助金関連度レベル === 2 ? '中' : r.補助金関連度レベル === 3 ? '高' : '';
      const activeText = r.有効フラグ ? '有効' : '無効';
      const startDate = r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString('ja-JP') : '';
      const endDate = r.適用終了日 ? new Date(r.適用終了日).toLocaleDateString('ja-JP') : '';
      const period = endDate ? `${startDate} ～ ${endDate}` : startDate;

      return `
        <tr data-id="${r.分類基準ID || r.id || ''}">
          <td style="padding: 6px 10px;">${r.分類基準名 || ''}</td>
          <td style="padding: 6px 10px;">${r.文書種別名 || ''}</td>
          <td style="padding: 6px 10px;">${subsidyLevelText}</td>
          <td style="padding: 6px 10px;">${r.処理ルート名 || ''}</td>
          <td style="padding: 6px 10px;">${r.優先度 || ''}</td>
          <td style="padding: 6px 10px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${r.有効フラグ ? 'var(--primary)' : 'rgba(255,255,255,0.1)'}; color: #fff;">
              ${activeText}
            </span>
          </td>
          <td style="padding: 6px 10px;">${period}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary edit-btn" data-id="${r.分類基準ID || r.id || ''}" style="margin-right: 4px; font-size: 11px; padding: 4px 8px;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${r.分類基準ID || r.id || ''}" style="font-size: 11px; padding: 4px 8px;">削除</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderRows(rows);
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    window.aivicApi.list(0).then(rows => {
      if (rows) {
        const filtered = rows.filter(r => 
          (r.分類基準名 || '').toLowerCase().includes(keyword) ||
          (r.文書種別名 || '').toLowerCase().includes(keyword)
        );
        renderRows(filtered);
      }
    });
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    window.aivicApi.list(0).then(rows => {
      if (!rows) return;

      const headers = ['分類基準名', '文書種別', '補助金関連度', '処理ルート', '優先度', '有効状態', '適用開始日', '適用終了日'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(r => [
          `"${r.分類基準名 || ''}"`,
          `"${r.文書種別名 || ''}"`,
          `"${r.補助金関連度レベル === 1 ? '低' : r.補助金関連度レベル === 2 ? '中' : r.補助金関連度レベル === 3 ? '高' : ''}"`,
          `"${r.処理ルート名 || ''}"`,
          `"${r.優先度 || ''}"`,
          `"${r.有効フラグ ? '有効' : '無効'}"`,
          `"${r.適用開始日 || ''}"`,
          `"${r.適用終了日 || ''}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '分類基準一覧.csv';
      link.click();
    });
  });

  // 4. 新規作成ボタン
  container.querySelector("#btn-create").addEventListener("click", () => {
    editingId = null;
    container.querySelector("#modal-title").textContent = "新規分類基準作成";
    clearForm();
    container.querySelector("#classification-modal").style.display = "block";
  });

  // 優先度スライダーの値表示更新
  container.querySelector("#input-priority").addEventListener("input", (e) => {
    container.querySelector("#priority-value").textContent = e.target.value;
  });

  // プレビュー機能
  container.querySelector("#btn-preview").addEventListener("click", () => {
    const name = container.querySelector("#input-name").value;
    const docType = container.querySelector("#select-document-type").value;
    const subsidyLevel = container.querySelector('input[name="subsidy-level"]:checked')?.value;
    const keywords = container.querySelector("#input-keywords").value;
    const route = container.querySelector("#select-route").value;
    const priority = container.querySelector("#input-priority").value;
    const active = container.querySelector("#input-active").checked;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    const subsidyText = subsidyLevel === '1' ? '低' : subsidyLevel === '2' ? '中' : subsidyLevel === '3' ? '高' : '未設定';

    const previewContent = `
      <strong>分類基準名:</strong> ${name || '未入力'}<br>
      <strong>文書種別:</strong> ${docType || '未選択'}<br>
      <strong>補助金関連度:</strong> ${subsidyText}<br>
      <strong>キーワード条件:</strong> ${keywords || '未入力'}<br>
      <strong>処理ルート:</strong> ${route || '未選択'}<br>
      <strong>優先度:</strong> ${priority}<br>
      <strong>有効状態:</strong> ${active ? '有効' : '無効'}<br>
      <strong>適用期間:</strong> ${startDate || '未設定'} ～ ${endDate || '無期限'}
    `;

    container.querySelector("#preview-content").innerHTML = previewContent;
    container.querySelector("#preview-area").style.display = "block";
  });

  // 5. 保存処理
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const name = container.querySelector("#input-name").value.trim();
    const docType = container.querySelector("#select-document-type").value;
    const subsidyLevel = container.querySelector('input[name="subsidy-level"]:checked')?.value;
    const keywords = container.querySelector("#input-keywords").value.trim();
    const route = container.querySelector("#select-route").value;
    const priority = parseInt(container.querySelector("#input-priority").value);
    const active = container.querySelector("#input-active").checked;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    // バリデーション
    if (!name) {
      alert("分類基準名を入力してください");
      return;
    }
    if (!docType) {
      alert("文書種別を選択してください");
      return;
    }
    if (!subsidyLevel) {
      alert("補助金関連度を選択してください");
      return;
    }
    if (!keywords) {
      alert("キーワード条件を入力してください");
      return;
    }
    if (!route) {
      alert("処理ルートを選択してください");
      return;
    }
    if (!startDate) {
      alert("適用開始日を入力してください");
      return;
    }
    if (endDate && new Date(startDate) > new Date(endDate)) {
      alert("適用開始日が終了日より後になっています");
      return;
    }

    // 過去日付チェック
    const today = new Date().toISOString().split('T')[0];
    if (startDate < today) {
      alert("適用日付は本日以降の日付を設定してください");
      return;
    }

    // 重複チェック（編集時は自分以外）
    const existingRows = await window.aivicApi.list(0);
    if (existingRows) {
      const duplicate = existingRows.find(r => 
        r.分類基準名 === name && 
        (editingId ? (r.分類基準ID || r.id) !== editingId : true)
      );
      if (duplicate) {
        alert("同じ分類基準名が既に存在します");
        return;
      }
    }

    const data = {
      分類基準名: name,
      文書種別名: docType,
      補助金関連度レベル: parseInt(subsidyLevel),
      キーワード条件: keywords,
      処理ルート名: route,
      優先度: priority,
      有効フラグ: active,
      適用開始日: startDate,
      適用終了日: endDate || null,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    let result;
    if (editingId) {
      result = await window.aivicApi.update(0, editingId, data);
    } else {
      result = await window.aivicApi.save(0, data);
    }

    if (result) {
      alert("分類基準を保存しました");
      container.querySelector("#classification-modal").style.display = "none";
      window.aivicApi.list(0).then(rows => {
        if (rows) renderRows(rows);
      });
    }
  });

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#classification-modal").style.display = "none";
  });

  container.querySelector("#btn-cancel").addEventListener("click", () => {
    container.querySelector("#classification-modal").style.display = "none";
  });

  // 削除確認モーダル
  container.querySelector("#btn-cancel-delete").addEventListener("click", () => {
    container.querySelector("#delete-modal").style.display = "none";
  });

  container.querySelector("#btn-confirm-delete").addEventListener("click", async () => {
    if (deleteTargetId) {
      await window.aivicApi.delete(0, deleteTargetId);
      container.querySelector("#delete-modal").style.display = "none";
      window.aivicApi.list(0).then(rows => {
        if (rows) renderRows(rows);
      });
    }
  });

  // 6. イベントデリゲーション（編集・削除）
  container.addEventListener("click", async (e) => {
    const editBtn = e.target.closest(".edit-btn");
    const deleteBtn = e.target.closest(".delete-btn");

    if (editBtn) {
      editingId = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const row = rows.find(r => (r.分類基準ID || r.id) === editingId);
        if (row) {
          container.querySelector("#modal-title").textContent = "分類基準編集";
          container.querySelector("#input-name").value = row.分類基準名 || '';
          container.querySelector("#select-document-type").value = row.文書種別名 || '';

          const subsidyRadio = container.querySelector(`input[name="subsidy-level"][value="${row.補助金関連度レベル}"]`);
          if (subsidyRadio) subsidyRadio.checked = true;

          container.querySelector("#input-keywords").value = row.キーワード条件 || '';
          container.querySelector("#select-route").value = row.処理ルート名 || '';
          container.querySelector("#input-priority").value = row.優先度 || 1;
          container.querySelector("#priority-value").textContent = row.優先度 || 1;
          container.querySelector("#input-active").checked = row.有効フラグ !== false;
          container.querySelector("#input-start-date").value = row.適用開始日 ? row.適用開始日.split('T')[0] : '';
          container.querySelector("#input-end-date").value = row.適用終了日 ? row.適用終了日.split('T')[0] : '';

          container.querySelector("#classification-modal").style.display = "block";
        }
      }
    }

    if (deleteBtn) {
      deleteTargetId = deleteBtn.dataset.id;
      container.querySelector("#delete-modal").style.display = "block";
    }
  });

  function clearForm() {
    container.querySelector("#input-name").value = '';
    container.querySelector("#select-document-type").value = '';
    container.querySelectorAll('input[name="subsidy-level"]').forEach(r => r.checked = false);
    container.querySelector("#input-keywords").value = '';
    container.querySelector("#select-route").value = '';
    container.querySelector("#input-priority").value = 1;
    container.querySelector("#priority-value").textContent = 1;
    container.querySelector("#input-active").checked = true;
    container.querySelector("#input-start-date").value = '';
    container.querySelector("#input-end-date").value = '';
    container.querySelector("#preview-area").style.display = "none";
  }

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#input-start-date").value = today;
}

function(container, apiUrl, tables) {
  let currentRouteId = null;
  let approvalSteps = [];
  let stepCounter = 1;

  // URLパラメータから処理ルートIDを取得
  const urlParams = new URLSearchParams(window.location.search);
  currentRouteId = urlParams.get('routeId') || 'route-001';

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 承認ステップテーブル再描画
  function renderApprovalSteps() {
    const tbody = container.querySelector('#approval-steps-tbody');
    tbody.innerHTML = approvalSteps.map((step, index) => `
      <tr data-step-id="${step.id}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <div style="display: flex; align-items: center; gap: 4px;">
            <span>${index + 1}</span>
            <button class="action-btn secondary move-up-btn" data-step-id="${step.id}" ${index === 0 ? 'disabled' : ''} 
                    style="padding: 2px 6px; font-size: 11px;">↑</button>
            <button class="action-btn secondary move-down-btn" data-step-id="${step.id}" ${index === approvalSteps.length - 1 ? 'disabled' : ''} 
                    style="padding: 2px 6px; font-size: 11px;">↓</button>
          </div>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${step.approverName}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${step.position}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${step.required ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 'background: rgba(156, 163, 175, 0.2); color: #9ca3af;'}">
            ${step.required ? '必須' : '任意'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${step.proxyAllowed ? 'background: rgba(59, 130, 246, 0.2); color: #3b82f6;' : 'background: rgba(156, 163, 175, 0.2); color: #9ca3af;'}">
            ${step.proxyAllowed ? '許可' : '不許可'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <button class="action-btn secondary delete-step-btn" data-step-id="${step.id}" style="padding: 4px 8px; font-size: 11px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 処理ルートデータ読み込み
  async function loadRouteData() {
    try {
      // 処理ルートデータを取得（実際のAPIでは currentRouteId で検索）
      const routes = await window.aivicApi.list(6); // 処理ルートテーブル
      const route = routes.find(r => r.処理ルートID === currentRouteId) || routes[0];

      if (route) {
        container.querySelector('#route-id').value = route.処理ルートID || currentRouteId;
        container.querySelector('#route-name').value = route.申請書類ID || '経費申請承認ルート';
        container.querySelector('#document-type').value = 'expense';
        container.querySelector('#subsidy-level').value = '2';
        container.querySelector('#deadline-days').value = '7';
        container.querySelector('#warning-days').value = '5';
        container.querySelector('#escalation-days').value = '10';

        // 承認ステップの初期データ
        approvalSteps = [
          {
            id: 'step-1',
            approverName: '田中 太郎',
            position: '部長',
            required: true,
            proxyAllowed: true
          },
          {
            id: 'step-2', 
            approverName: '佐藤 花子',
            position: '課長',
            required: true,
            proxyAllowed: false
          }
        ];
        renderApprovalSteps();
      }
    } catch (error) {
      showError('処理ルートデータの読み込みに失敗しました');
    }
  }

  // 承認者追加モーダル制御
  const modal = container.querySelector('#approver-modal');
  const addApproverBtn = container.querySelector('#add-approver-btn');
  const modalCancelBtn = container.querySelector('#modal-cancel-btn');
  const modalAddBtn = container.querySelector('#modal-add-btn');

  addApproverBtn.addEventListener('click', () => {
    modal.style.display = 'block';
    container.querySelector('#modal-approver').value = '';
    container.querySelector('#modal-required').checked = false;
    container.querySelector('#modal-proxy').checked = false;
  });

  modalCancelBtn.addEventListener('click', () => {
    modal.style.display = 'none';
  });

  modalAddBtn.addEventListener('click', () => {
    const approverSelect = container.querySelector('#modal-approver');
    const required = container.querySelector('#modal-required').checked;
    const proxyAllowed = container.querySelector('#modal-proxy').checked;

    if (!approverSelect.value) {
      showError('承認者を選択してください');
      return;
    }

    const approverText = approverSelect.options[approverSelect.selectedIndex].text;
    const [name, position] = approverText.split(' (');

    approvalSteps.push({
      id: `step-${++stepCounter}`,
      approverName: name,
      position: position ? position.replace(')', '') : '',
      required: required,
      proxyAllowed: proxyAllowed
    });

    renderApprovalSteps();
    modal.style.display = 'none';
  });

  // 承認ステップ操作（削除・並び替え）
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-step-btn');
    const moveUpBtn = e.target.closest('.move-up-btn');
    const moveDownBtn = e.target.closest('.move-down-btn');

    if (deleteBtn) {
      const stepId = deleteBtn.dataset.stepId;
      if (confirm('この承認ステップを削除しますか？')) {
        approvalSteps = approvalSteps.filter(step => step.id !== stepId);
        renderApprovalSteps();
      }
    }

    if (moveUpBtn && !moveUpBtn.disabled) {
      const stepId = moveUpBtn.dataset.stepId;
      const index = approvalSteps.findIndex(step => step.id === stepId);
      if (index > 0) {
        [approvalSteps[index - 1], approvalSteps[index]] = [approvalSteps[index], approvalSteps[index - 1]];
        renderApprovalSteps();
      }
    }

    if (moveDownBtn && !moveDownBtn.disabled) {
      const stepId = moveDownBtn.dataset.stepId;
      const index = approvalSteps.findIndex(step => step.id === stepId);
      if (index < approvalSteps.length - 1) {
        [approvalSteps[index], approvalSteps[index + 1]] = [approvalSteps[index + 1], approvalSteps[index]];
        renderApprovalSteps();
      }
    }
  });

  // 更新ボタン
  container.querySelector('#update-btn').addEventListener('click', async () => {
    const routeName = container.querySelector('#route-name').value.trim();
    const documentType = container.querySelector('#document-type').value;
    const subsidyLevel = container.querySelector('#subsidy-level').value;
    const deadlineDays = container.querySelector('#deadline-days').value;
    const warningDays = container.querySelector('#warning-days').value;
    const escalationDays = container.querySelector('#escalation-days').value;

    // バリデーション
    if (!routeName) {
      showError('処理ルート名を入力してください');
      return;
    }

    if (routeName.length > 100) {
      showError('処理ルート名は100文字以内で入力してください');
      return;
    }

    if (!documentType) {
      showError('文書種別を選択してください');
      return;
    }

    if (approvalSteps.length === 0) {
      showError('承認者を設定してください');
      return;
    }

    const requiredSteps = approvalSteps.filter(step => step.required);
    if (requiredSteps.length === 0) {
      showError('必須承認者が設定されていません');
      return;
    }

    if (deadlineDays && (isNaN(deadlineDays) || parseInt(deadlineDays) < 0)) {
      showError('遅延検知設定には正の数値を入力してください');
      return;
    }

    if (warningDays && (isNaN(warningDays) || parseInt(warningDays) < 0)) {
      showError('遅延検知設定には正の数値を入力してください');
      return;
    }

    if (escalationDays && (isNaN(escalationDays) || parseInt(escalationDays) < 0)) {
      showError('遅延検知設定には正の数値を入力してください');
      return;
    }

    if (!confirm('処理ルートを更新しますか？')) {
      return;
    }

    try {
      // 処理ルート更新
      const routeData = {
        処理ルートID: currentRouteId,
        申請書類ID: routeName,
        承認フロー定義ID: documentType,
        現在ステップ番号: 1,
        処理状況: '設定済み',
        開始日時: new Date().toISOString(),
        優先度: parseInt(subsidyLevel) || 2,
        自動処理フラグ: false,
        備考: `承認ステップ数: ${approvalSteps.length}`,
        更新日時: new Date().toISOString(),
        更新者ID: 'current-user'
      };

      const updated = await window.aivicApi.update(6, currentRouteId, routeData);

      if (updated) {
        // 遅延検知設定更新
        if (deadlineDays || warningDays || escalationDays) {
          const delayData = {
            文書種別ID: documentType,
            設定名: `${routeName}_遅延検知設定`,
            期限日数: parseInt(deadlineDays) || 7,
            警告日数: parseInt(warningDays) || 5,
            エスカレーション日数: parseInt(escalationDays) || 10,
            営業日計算フラグ: true,
            有効フラグ: true,
            更新日時: new Date().toISOString(),
            更新者ID: 'current-user'
          };
          await window.aivicApi.save(7, delayData);
        }

        alert('処理ルートが正常に更新されました');
        window.showScreen('scr-1779422354662');
      } else {
        showError('処理ルートの更新に失敗しました');
      }
    } catch (error) {
      if (error.message && error.message.includes('競合')) {
        showError('他のユーザーが編集中のため更新できません');
      } else if (error.message && error.message.includes('権限')) {
        showError('この機能にアクセスする権限がありません');
      } else if (error.message && error.message.includes('ネットワーク')) {
        showError('ネットワークエラーが発生しました。接続を確認してください');
      } else {
        showError('処理ルートの更新中にエラーが発生しました');
      }
    }
  });

  // 初期データ読み込み
  loadRouteData();
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let detectionHistory = [];

  // DOM要素の取得
  const fileUpload = container.querySelector('#file-upload');
  const btnUpload = container.querySelector('#btn-upload');
  const fileInfo = container.querySelector('#file-info');
  const autoDetectionResult = container.querySelector('#auto-detection-result');
  const accuracyFill = container.querySelector('#accuracy-fill');
  const accuracyText = container.querySelector('#accuracy-text');
  const subsidyScore = container.querySelector('#subsidy-score');
  const manualDocumentType = container.querySelector('#manual-document-type');
  const documentPreview = container.querySelector('#document-preview');
  const historyTbody = container.querySelector('#history-tbody');
  const errorMessage = container.querySelector('#error-message');
  const btnReDetect = container.querySelector('#btn-re-detect');
  const btnConfirmFlow = container.querySelector('#btn-confirm-flow');
  const btnFinalize = container.querySelector('#btn-finalize');
  const btnDigitizationCheck = container.querySelector('#btn-digitization-check');
  const masterReferenceLink = container.querySelector('#master-reference-link');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 判定履歴の再描画
  function renderHistory() {
    historyTbody.innerHTML = detectionHistory.map(h => `
      <tr>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${h.detectionDate}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${h.fileName}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${h.result}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${h.accuracy}%</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${h.detector}</td>
      </tr>
    `).join('');
  }

  // ファイル選択時の処理
  fileUpload.addEventListener('change', function(e) {
    const file = e.target.files[0];
    if (!file) {
      fileInfo.textContent = 'ファイルが選択されていません';
      currentFile = null;
      return;
    }

    // ファイル形式チェック
    const allowedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx'];
    const fileExtension = '.' + file.name.split('.').pop().toLowerCase();
    if (!allowedTypes.includes(fileExtension)) {
      showError('対応していないファイル形式です。PDF、Word、Excel形式のファイルをアップロードしてください。');
      fileUpload.value = '';
      return;
    }

    // ファイルサイズチェック（10MB制限）
    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      showError('ファイルサイズが上限（10MB）を超えています。');
      fileUpload.value = '';
      return;
    }

    currentFile = file;
    fileInfo.innerHTML = `
      <strong>${file.name}</strong><br>
      サイズ: ${(file.size / 1024).toFixed(1)} KB<br>
      形式: ${fileExtension.toUpperCase()}
    `;
  });

  // アップロード処理
  btnUpload.addEventListener('click', async function() {
    if (!currentFile) {
      showError('ファイルを選択してください。');
      return;
    }

    try {
      // ファイルの内容を読み取り（プレビュー用）
      const reader = new FileReader();
      reader.onload = function(e) {
        if (currentFile.type === 'application/pdf') {
          documentPreview.innerHTML = `
            <div style="text-align: center; padding: 40px;">
              <div style="font-size: 48px; margin-bottom: 12px;">📄</div>
              <div>PDFファイル: ${currentFile.name}</div>
              <div style="font-size: 11px; color: var(--text-muted); margin-top: 8px;">
                プレビューを表示するには専用ビューアーが必要です
              </div>
            </div>
          `;
        } else {
          documentPreview.innerHTML = `
            <div style="text-align: center; padding: 40px;">
              <div style="font-size: 48px; margin-bottom: 12px;">📊</div>
              <div>${currentFile.name}</div>
              <div style="font-size: 11px; color: var(--text-muted); margin-top: 8px;">
                ファイルが正常にアップロードされました
              </div>
            </div>
          `;
        }
      };
      reader.readAsText(currentFile);

      // 自動判定の実行
      await performAutoDetection();

    } catch (error) {
      showError('ファイルの処理中にエラーが発生しました。');
    }
  });

  // 自動判定処理
  async function performAutoDetection() {
    if (!currentFile) return;

    // ファイル名から簡易判定
    const fileName = currentFile.name.toLowerCase();
    let detectedType = 'その他';
    let accuracy = 0;
    let subsidyRelevance = 0;

    if (fileName.includes('経費') || fileName.includes('expense')) {
      detectedType = '経費申請書';
      accuracy = 85;
      subsidyRelevance = 20;
    } else if (fileName.includes('休暇') || fileName.includes('leave')) {
      detectedType = '休暇申請書';
      accuracy = 90;
      subsidyRelevance = 0;
    } else if (fileName.includes('補助金') || fileName.includes('subsidy')) {
      detectedType = '補助金申請書';
      accuracy = 95;
      subsidyRelevance = 100;
    } else if (fileName.includes('調達') || fileName.includes('procurement')) {
      detectedType = '調達依頼書';
      accuracy = 80;
      subsidyRelevance = 30;
    } else if (fileName.includes('契約') || fileName.includes('contract')) {
      detectedType = '契約書類';
      accuracy = 75;
      subsidyRelevance = 15;
    } else {
      // ランダムな判定結果を生成
      const types = ['経費申請書', '休暇申請書', '補助金申請書', '調達依頼書', '契約書類'];
      detectedType = types[Math.floor(Math.random() * types.length)];
      accuracy = Math.floor(Math.random() * 60) + 40; // 40-99%
      subsidyRelevance = Math.floor(Math.random() * 50);
    }

    // 結果の表示
    autoDetectionResult.textContent = detectedType;
    accuracyFill.style.width = accuracy + '%';
    accuracyText.textContent = accuracy + '%';
    subsidyScore.textContent = subsidyRelevance + '点';

    // 精度に応じた色の変更
    if (accuracy >= 80) {
      accuracyFill.style.background = '#10b981'; // 緑
    } else if (accuracy >= 60) {
      accuracyFill.style.background = '#f59e0b'; // 黄
    } else {
      accuracyFill.style.background = '#ef4444'; // 赤
    }

    // 手動選択を自動判定結果に合わせる
    const typeMapping = {
      '経費申請書': 'expense-application',
      '休暇申請書': 'leave-application',
      '補助金申請書': 'subsidy-application',
      '調達依頼書': 'procurement-request',
      '契約書類': 'contract-document',
      'その他': 'other'
    };
    manualDocumentType.value = typeMapping[detectedType] || 'other';

    // 履歴に追加
    detectionHistory.unshift({
      detectionDate: new Date().toLocaleString('ja-JP'),
      fileName: currentFile.name,
      result: detectedType,
      accuracy: accuracy,
      detector: '自動判定'
    });
    renderHistory();
  }

  // 再判定処理
  btnReDetect.addEventListener('click', async function() {
    if (!currentFile) {
      showError('再判定するファイルがありません。');
      return;
    }
    await performAutoDetection();
  });

  // 承認フロー確認
  btnConfirmFlow.addEventListener('click', function() {
    const selectedType = manualDocumentType.value;
    if (!selectedType) {
      showError('文書種別を選択してください。');
      return;
    }
    alert(`選択された文書種別「${manualDocumentType.options[manualDocumentType.selectedIndex].text}」の承認フローを確認します。`);
  });

  // 判定確定処理
  btnFinalize.addEventListener('click', async function() {
    const selectedType = manualDocumentType.value;
    if (!selectedType) {
      showError('文書種別を選択してください。');
      return;
    }

    if (!currentFile) {
      showError('確定するファイルがありません。');
      return;
    }

    try {
      // 判定結果を保存
      const result = {
        fileName: currentFile.name,
        documentType: selectedType,
        detectionResult: autoDetectionResult.textContent,
        accuracy: parseInt(accuracyText.textContent),
        subsidyScore: parseInt(subsidyScore.textContent),
        finalizedAt: new Date().toISOString(),
        finalizedBy: 'current-user'
      };

      // APIに保存（文書種別マスタテーブルを使用）
      const saved = await window.aivicApi.save(2, result);
      if (saved) {
        alert('文書種別の判定が確定されました。');

        // 履歴に確定記録を追加
        detectionHistory.unshift({
          detectionDate: new Date().toLocaleString('ja-JP'),
          fileName: currentFile.name,
          result: manualDocumentType.options[manualDocumentType.selectedIndex].text,
          accuracy: parseInt(accuracyText.textContent),
          detector: '手動確定'
        });
        renderHistory();
      }
    } catch (error) {
      showError('判定結果の保存に失敗しました。');
    }
  });

  // 文書種別マスタ参照リンク
  masterReferenceLink.addEventListener('click', function(e) {
    e.preventDefault();
    alert('文書種別マスタ画面に遷移します。');
  });

  // 電子化可否判定画面への遷移
  btnDigitizationCheck.addEventListener('click', function() {
    window.showScreen("scr-1779422575885");
  });

  // 初期履歴データの表示
  renderHistory();

  // 初期データがある場合の表示
  if (tables && tables[2] && tables[2].records) {
    // 文書種別マスタからオプションを動的生成
    const masterRecords = tables[2].records;
    if (masterRecords.length > 0) {
      const additionalOptions = masterRecords.map(record => 
        `<option value="${record.文書種別コード || record.id}">${record.文書種別名 || record.name || 'Unknown'}</option>`
      ).join('');

      // 既存のオプションの後に追加
      manualDocumentType.innerHTML += additionalOptions;
    }
  }
}

function(container, apiUrl, tables) {
  let currentApplicationId = null;
  let currentJudgmentData = null;

  // 初期データの設定
  function initializeData() {
    const applications = tables[1]?.records || [];
    const documentTypes = tables[2]?.records || [];
    const subsidyLevels = tables[9]?.records || [];

    if (applications.length > 0) {
      const app = applications[0];
      currentApplicationId = app.申請書類ID;
      container.querySelector("#application-id-display").textContent = app.申請書類ID || "APP-2024-001";
      container.querySelector("#applicant-name").textContent = app.申請者名 || "田中 太郎";
      container.querySelector("#applicant-dept").textContent = app.申請者部署 || "総務部";
      container.querySelector("#application-date").textContent = app.作成日時 ? new Date(app.作成日時).toLocaleString('ja-JP') : "2024-01-15 14:30";

      // プレビュー更新
      const preview = container.querySelector("#document-preview");
      preview.innerHTML = `
        <div>申請タイトル: ${app.申請タイトル || "備品購入申請"}</div>
        <div>申請内容: ${app.申請内容 || "オフィス用プリンター購入のための申請です。"}</div>
        <div>申請金額: ${app.申請金額 ? app.申請金額.toLocaleString() + "円" : "150,000円"}</div>
        <div>申請期間: ${app.申請開始日 || "2024-02-01"} ～ ${app.申請終了日 || "2024-02-28"}</div>
      `;
    }

    // 文書種別の選択肢を更新
    const docTypeSelect = container.querySelector("#document-type");
    if (documentTypes.length > 0) {
      docTypeSelect.innerHTML = '<option value="">選択してください</option>';
      documentTypes.forEach(type => {
        const option = document.createElement('option');
        option.value = type.文書種別コード;
        option.textContent = type.文書種別名;
        docTypeSelect.appendChild(option);
      });
    }
  }

  // 判定実行
  async function executeJudgment() {
    const docType = container.querySelector("#document-type").value;
    const errorDiv = container.querySelector("#error-message");

    // バリデーション
    if (!docType) {
      showError("文書種別を選択してください");
      return;
    }

    if (!currentApplicationId) {
      showError("申請書類IDが正しくありません");
      return;
    }

    try {
      // 判定ロジック
      const isSubsidyRelated = docType === "subsidy" || docType === "contract";
      const subsidyLevel = isSubsidyRelated ? "高" : docType === "application" ? "中" : "低";
      const canDigitize = docType !== "contract"; // 契約書は電子化不可とする
      const recommendedRoute = isSubsidyRelated ? "ハイブリッド" : canDigitize ? "電子のみ" : "紙のみ";

      let judgmentReason = "";
      if (canDigitize) {
        judgmentReason = `文書種別「${docType}」は電子化処理が可能です。`;
        if (isSubsidyRelated) {
          judgmentReason += " 補助金関連のため、ハイブリッド処理を推奨します。";
        } else {
          judgmentReason += " 電子処理での効率化が期待できます。";
        }
      } else {
        judgmentReason = `文書種別「${docType}」は署名・押印が必要なため電子化処理ができません。紙での処理が必要です。`;
      }

      // 結果表示の更新
      const resultStatus = container.querySelector("#result-status");
      const levelValue = container.querySelector("#level-value");
      const routeValue = container.querySelector("#route-value");
      const reasonTextarea = container.querySelector("#judgment-reason");

      resultStatus.textContent = canDigitize ? "電子化可能" : "電子化不可";
      resultStatus.style.color = canDigitize ? "#4ade80" : "#f87171";

      levelValue.textContent = subsidyLevel;
      routeValue.textContent = recommendedRoute;
      reasonTextarea.value = judgmentReason;

      // 判定データを保存
      currentJudgmentData = {
        申請書類ID: currentApplicationId,
        文書種別: docType,
        判定結果: canDigitize ? "可" : "不可",
        補助金関連度: subsidyLevel,
        推奨ルート: recommendedRoute,
        判定理由: judgmentReason,
        判定日時: new Date().toISOString(),
        判定者ID: "current-user"
      };

      hideError();

    } catch (error) {
      showError("判定実行時にシステムエラーが発生しました");
      console.error("Judgment execution error:", error);
    }
  }

  // 手動オーバーライド処理
  function handleManualOverride() {
    const checkbox = container.querySelector("#manual-override");
    const resultStatus = container.querySelector("#result-status");
    const reasonTextarea = container.querySelector("#judgment-reason");

    if (checkbox.checked && currentJudgmentData) {
      const currentResult = currentJudgmentData.判定結果;
      const newResult = currentResult === "可" ? "不可" : "可";
      const newStatus = newResult === "可" ? "電子化可能" : "電子化不可";

      resultStatus.textContent = newStatus + " (手動変更)";
      resultStatus.style.color = newResult === "可" ? "#4ade80" : "#f87171";

      reasonTextarea.value = currentJudgmentData.判定理由 + "\n\n[手動オーバーライド] 管理者により判定結果を変更しました。";

      currentJudgmentData.判定結果 = newResult;
      currentJudgmentData.手動変更フラグ = true;
      currentJudgmentData.変更理由 = "管理者による手動オーバーライド";
    } else if (currentJudgmentData) {
      // オーバーライド解除
      const originalResult = currentJudgmentData.判定結果 === "可" ? "不可" : "可";
      const originalStatus = originalResult === "可" ? "電子化可能" : "電子化不可";

      resultStatus.textContent = originalStatus;
      resultStatus.style.color = originalResult === "可" ? "#4ade80" : "#f87171";

      reasonTextarea.value = currentJudgmentData.判定理由.split("\n\n[手動オーバーライド]")[0];

      currentJudgmentData.判定結果 = originalResult;
      delete currentJudgmentData.手動変更フラグ;
      delete currentJudgmentData.変更理由;
    }
  }

  // 承認フロー確認
  function checkApprovalFlow() {
    if (!currentApplicationId) {
      showError("申請書類が選択されていません");
      return;
    }

    try {
      // 承認フロー確認画面への遷移（実際の画面IDに置き換える）
      alert("承認フロー確認画面に遷移します");
    } catch (error) {
      showError("承認フロー確認時にエラーが発生しました");
      console.error("Approval flow check error:", error);
    }
  }

  // 次のステップへ
  async function proceedToNextStep() {
    if (!currentJudgmentData) {
      showError("判定を実行してください");
      return;
    }

    try {
      // 判定結果を保存
      const saved = await window.aivicApi.save(1, currentJudgmentData);
      if (saved) {
        alert("電子化可否判定が完了しました。次のステップに進みます。");
        // 実際の次画面への遷移処理
      } else {
        showError("判定結果の保存に失敗しました");
      }
    } catch (error) {
      showError("次のステップへの進行中にエラーが発生しました");
      console.error("Next step error:", error);
    }
  }

  // 処理ルート設定画面への遷移
  function goToRouteSettings() {
    window.showScreen("scr-1779422591281");
  }

  // エラー表示/非表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.style.display = "block";
  }

  function hideError() {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.style.display = "none";
  }

  // 文書種別変更時の処理
  function handleDocumentTypeChange() {
    const docType = container.querySelector("#document-type").value;
    if (docType) {
      // 判定条件の更新（文書種別に応じた条件表示）
      const subsidyLevels = tables[9]?.records || [];
      const level = subsidyLevels.find(l => l.文書種別 === docType);
      if (level) {
        container.querySelector("#level-value").textContent = level.関連度レベル || "中";
      }
    }
  }

  // イベントリスナーの設定
  container.querySelector("#btn-execute-judgment").addEventListener("click", executeJudgment);
  container.querySelector("#btn-check-approval-flow").addEventListener("click", checkApprovalFlow);
  container.querySelector("#btn-next-step").addEventListener("click", proceedToNextStep);
  container.querySelector("#btn-route-setting").addEventListener("click", goToRouteSettings);
  container.querySelector("#manual-override").addEventListener("change", handleManualOverride);
  container.querySelector("#document-type").addEventListener("change", handleDocumentTypeChange);

  // 初期化
  initializeData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#document-tbody");
  const resultsCount = container.querySelector("#results-count");
  const noResults = container.querySelector("#no-results");
  const errorMessage = container.querySelector("#error-message");
  const errorText = container.querySelector("#error-text");

  let allDocuments = [];
  let userMap = {};
  let flowMap = {};
  let routeMap = {};

  // ユーザーマップを構築
  if (tables[0]) {
    tables[0].records.forEach(user => {
      userMap[user.ユーザーID] = user.ユーザー名;
    });
  }

  // 承認フローマップを構築
  if (tables[3]) {
    tables[3].records.forEach(flow => {
      flowMap[flow.承認フローID] = flow.承認フロー名;
    });
  }

  // 処理ルートマップを構築
  if (tables[6]) {
    tables[6].records.forEach(route => {
      routeMap[route.申請書類ID] = route;
    });
  }

  function showError(message) {
    errorText.textContent = message;
    errorMessage.style.display = "block";
    setTimeout(() => {
      errorMessage.style.display = "none";
    }, 5000);
  }

  function validateDateRange() {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }
    return true;
  }

  function renderRows(documents) {
    if (!documents || documents.length === 0) {
      tbody.innerHTML = "";
      resultsCount.textContent = "0";
      noResults.style.display = "block";
      return;
    }

    noResults.style.display = "none";
    resultsCount.textContent = documents.length.toString();

    tbody.innerHTML = documents.map(doc => {
      const applicantName = userMap[doc.申請者ID] || "不明";
      const approverName = userMap[doc.現在承認者ID] || "なし";
      const route = routeMap[doc.申請書類ID];
      const routeName = route ? flowMap[route.承認フロー定義ID] || "不明" : "未設定";
      const createdDate = doc.作成日時 ? new Date(doc.作成日時).toLocaleDateString('ja-JP') : "";

      const statusBadge = getStatusBadge(doc.承認状態);

      return `
        <tr data-id="${doc.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            <a href="#" class="document-link" data-id="${doc.申請書類ID}" style="color: var(--primary); text-decoration: none;">
              ${doc.申請書類ID ? doc.申請書類ID.substring(0, 8) : ""}
            </a>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${doc.申請種別 || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${doc.申請タイトル || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${applicantName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${createdDate}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${statusBadge}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${approverName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${routeName}</td>
        </tr>
      `;
    }).join("");
  }

  function getStatusBadge(status) {
    const statusColors = {
      "申請中": "background: rgba(59, 130, 246, 0.2); color: #3b82f6;",
      "承認待ち": "background: rgba(245, 158, 11, 0.2); color: #f59e0b;",
      "承認済": "background: rgba(34, 197, 94, 0.2); color: #22c55e;",
      "却下": "background: rgba(239, 68, 68, 0.2); color: #ef4444;",
      "差戻し": "background: rgba(168, 85, 247, 0.2); color: #a855f7;",
      "取下げ": "background: rgba(107, 114, 128, 0.2); color: #6b7280;"
    };

    const style = statusColors[status] || "background: rgba(107, 114, 128, 0.2); color: #6b7280;";
    return `<span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 500; ${style}">${status || ""}</span>`;
  }

  function filterDocuments() {
    if (!validateDateRange()) {
      return;
    }

    const keyword = container.querySelector("#input-keyword").value.toLowerCase();
    const documentType = container.querySelector("#select-document-type").value;
    const approvalStatus = container.querySelector("#select-approval-status").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const applicant = container.querySelector("#input-applicant").value.toLowerCase();
    const approver = container.querySelector("#input-approver").value.toLowerCase();
    const processRoute = container.querySelector("#select-process-route").value;
    const subsidyLevel = container.querySelector('input[name="subsidy-level"]:checked')?.value;

    let filtered = allDocuments.filter(doc => {
      // キーワード検索
      if (keyword) {
        const searchText = `${doc.申請タイトル || ""} ${doc.申請内容 || ""}`.toLowerCase();
        if (!searchText.includes(keyword)) return false;
      }

      // 文書種別
      if (documentType && doc.申請種別 !== documentType) return false;

      // 承認状態
      if (approvalStatus && doc.承認状態 !== approvalStatus) return false;

      // 申請日期間
      if (startDate || endDate) {
        const docDate = doc.作成日時 ? new Date(doc.作成日時).toISOString().split('T')[0] : "";
        if (startDate && docDate < startDate) return false;
        if (endDate && docDate > endDate) return false;
      }

      // 申請者名
      if (applicant) {
        const applicantName = (userMap[doc.申請者ID] || "").toLowerCase();
        if (!applicantName.includes(applicant)) return false;
      }

      // 承認者名
      if (approver) {
        const approverName = (userMap[doc.現在承認者ID] || "").toLowerCase();
        if (!approverName.includes(approver)) return false;
      }

      // 処理ルート
      if (processRoute) {
        const route = routeMap[doc.申請書類ID];
        const routeName = route ? flowMap[route.承認フロー定義ID] || "" : "";
        if (routeName !== processRoute) return false;
      }

      // 補助金関連度（簡易実装：申請内容に基づく判定）
      if (subsidyLevel) {
        const content = (doc.申請内容 || "").toLowerCase();
        const hasSubsidy = content.includes("補助金") || content.includes("助成");
        if (subsidyLevel === "高" && !hasSubsidy) return false;
        if (subsidyLevel === "低" && hasSubsidy) return false;
      }

      return true;
    });

    renderRows(filtered);
  }

  function clearSearchConditions() {
    container.querySelector("#input-keyword").value = "";
    container.querySelector("#select-document-type").value = "";
    container.querySelector("#select-approval-status").value = "";
    container.querySelector("#input-start-date").value = "";
    container.querySelector("#input-end-date").value = "";
    container.querySelector("#input-applicant").value = "";
    container.querySelector("#input-approver").value = "";
    container.querySelector("#select-process-route").value = "";

    const subsidyRadios = container.querySelectorAll('input[name="subsidy-level"]');
    subsidyRadios.forEach(radio => radio.checked = false);

    renderRows(allDocuments);
  }

  function exportToCSV() {
    const headers = ["文書番号", "申請種別", "申請タイトル", "申請者", "申請日", "承認状態", "現在承認者", "処理ルート"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...allDocuments.map(doc => {
        const applicantName = userMap[doc.申請者ID] || "不明";
        const approverName = userMap[doc.現在承認者ID] || "なし";
        const route = routeMap[doc.申請書類ID];
        const routeName = route ? flowMap[route.承認フロー定義ID] || "不明" : "未設定";
        const createdDate = doc.作成日時 ? new Date(doc.作成日時).toLocaleDateString('ja-JP') : "";

        return [
          `"${doc.申請書類ID ? doc.申請書類ID.substring(0, 8) : ""}"`,
          `"${doc.申請種別 || ""}"`,
          `"${doc.申請タイトル || ""}"`,
          `"${applicantName}"`,
          `"${createdDate}"`,
          `"${doc.承認状態 || ""}"`,
          `"${approverName}"`,
          `"${routeName}"`
        ].join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "電子文書検索結果.csv";
    link.click();
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(documents => {
    if (documents) {
      allDocuments = documents;
      renderRows(documents);
    } else {
      allDocuments = tables[1]?.records || [];
      renderRows(allDocuments);
    }
  }).catch(error => {
    console.error("データ取得エラー:", error);
    allDocuments = tables[1]?.records || [];
    renderRows(allDocuments);
  });

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", filterDocuments);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-csv-export").addEventListener("click", exportToCSV);

  // 文書番号リンククリック
  container.addEventListener("click", (e) => {
    const documentLink = e.target.closest(".document-link");
    if (documentLink) {
      e.preventDefault();
      const documentId = documentLink.dataset.id;
      // 申請書類確認画面へ遷移
      window.showScreen("scr-1779422434952");
    }
  });

  // 日付入力のバリデーション
  container.querySelector("#input-start-date").addEventListener("change", validateDateRange);
  container.querySelector("#input-end-date").addEventListener("change", validateDateRange);
}
